WITH payload AS (SELECT $archive_payload$[{"id":"cbfee9dd-2667-5846-8e55-f783f62e4ac3","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة عقد مضاربة -مطالبة بإعادة رأس املال -غياب املدعى عليه بعد أول جلسة -عجز عن إثبات الدفع بالوساطة -مين على نفي الدفع -ثبوت الدعوى واحلكم على املدعى عليه بدفع املبلغ املدعى به -تبليغ املدعى عليه الغائب عن مجلس احلكم بصورة من احلكم -حكم حضوري.","document_number":"342294287","case_number":"3342731","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/15","year":"1434","subject":"شراكة عقد مضاربة -مطالبة بإعادة رأس املال -غياب املدعى عليه بعد أول جلسة -عجز عن إثبات الدفع بالوساطة -مين على نفي الدفع -ثبوت الدعوى واحلكم على املدعى عليه بدفع املبلغ املدعى به -تبليغ املدعى عليه الغائب عن مجلس احلكم بصورة من احلكم -حكم حضوري.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/11/15 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪342294287 :‬‬\n                           ‫َر ْق ُم الدعوى‪3342731 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34362985‬تاريخه‪1434/11/19:‬هـ‬\n\n\n       ‫شــراكة عقــد مضاربــة ‪ -‬مطالبــة بإعــادة رأس املــال‪ -‬غيــاب املدعــى‬\n       ‫عليــه بعــد أول جلســة ‪ -‬عجــز عــن إثبــات الدفــع بالوســاطة‪ -‬ميــن علــى‬\n       ‫نفــي الدفــع ‪ -‬ثبــوت الدعــوى واحلكــم علــى املدعــى عليــه بدفــع املبلــغ‬\n       ‫املدعــى بــه ‪ -‬تبليــغ املدعــى عليــه الغائــب عــن مجلــس احلكــم بصــورة‬\n                                                      ‫مــن احلكــم‪ -‬حكــم حضــوري‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                                  ‫علــى مــن انكــر)‪.‬‬\n                                             ‫‪ -2‬على اليد ما أخذت حتى تؤديه‪.‬‬\n                                    ‫‪ -3‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n       ‫ادعــى وكيــل املدعــي أن موكلــه ســلم للمدعــى عليــه املبلــغ املذكــور‬\n       ‫يف الدعــوى بعــد أن اتفــق معــه علــى أن يتاجــر املدعــى عليــه بذلــك املبلــغ‬\n       ‫يف الشــيء الــذي يــراه مناســب ًا ويكــون حــاال وعلــى أن تكــون األربــاح‬\n       ‫مناصفــة فمــن موكلــه رأس املــال ومــن املدعى عليه العمل إال أن املدعى‬\n       ‫عليــه لــم يســلم موكلــه أي شــيء مــن األربــاح و ال مــن رأس املــال‪ ،‬ولــذا‬\n       ‫طلــب إلــزام املدعــى عليــه بــأن يعيــد لــه املبلــغ املســلم لــه‪ ،‬أنكــر املدعــى‬\n\n‫‪49‬‬\n\f‫عليــه وجــود اتفــاق بينــه وبــن املدعــي ودفــع بــأن خــال املدعــي قــام‬\n‫بتحويــل مبلــغ يعــادل املبلــغ املدعــى بــه وطلــب منــه أن يســلمه لصاحــب‬\n‫مســاهمة (ذكــر اســمه) وأنــه أوصــل املبلــغ للشــخص املذكــور‪ ،‬قــدم‬\n‫املدعــي حوالــة مصرفيــة تبــن حتويلــه املبلــغ املدعــى بــه حلســاب املدعــى‬\n‫عليــه‪ ،‬طلبــت احملكمــة مــن املدعــى عليــه إثبــات مــا دفــع بــه فعجــز عــن‬\n‫ذلــك وطلــب ميــن املدعــي علــى نفــي الدعــوى فأداهــا طبــق مــا طلــب منه‪،‬‬\n‫املدعــى عليــه أقــر باســتالمه املبلــغ ومــن املقــرر شــرع ًا بــأن علــى اليــد مــا‬\n‫أخــذت حتــى تؤديــه‪ ،‬قضــت احملكمــة حضوري ـ ًا بإلــزام املدعــى عليــه‬\n‫الغائــب عــن املجلــس الشــرعي بــأن يدفــع للمدعــي املبلــغ املدعــى بــه‪،‬‬\n‫قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه‪ ،‬قــررت محكمــة‬\n                   ‫االســتئناف املوافقــة علــى احلكــم بعــد االجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 3342731‬وتاريــخ ‪ 1433/01/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33108604‬وتاريــخ ‪ 1433/01/16‬ه ـ ويف يــوم‬\n‫االثنــن ‪ 1433/04/05‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 59‬للنظــر‬\n‫يف الدعــوى املرفوعــة مــن ‪ .....‬ضــد ‪ .....‬بطلــب حوالــة أو غــن أو نحــو‬\n‫ذلــك وفيهــا حضــر املدعــي وكالــة (‪ ).....‬يحمــل بطاقــة الهويــة الوطنيــة‬\n‫رقــم ‪ .....‬حالــة كونــه وكيــا عــن ‪ .....‬يحمــل ســجل مدنــي رقــم ‪.....‬‬\n‫بالوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة رقــم ‪19226‬‬\n‫تاريــخ ‪1433/4/3‬ه ـ جلــد ‪ 5700‬والتــي تخولــه حــق املدافعــة واملرافعــة‬\n\n                                                                                            ‫‪50‬‬\n\f     ‫واإلقــرار واإلنــكار وقبــول األحــكام ونفيهــا وحضــور اجللســات وتقــدمي‬\n     ‫البينــات وإحضــار الشــهود واســتالم املبلــغ ومراجعــة األحكام الشــرعية‬\n     ‫وادعــى علــى احلاضــر معــه ‪ .....‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪.....‬‬\n     ‫قائــا يف دعــواه إن موكلــي قــد ســلم املدعــى عليــه هــذا احلاضــر يف عــام‬\n     ‫‪1427‬ه ـ مبلــغ اثنــن وأربعــن ألفــا وخمســمائة ريــال وجــرى بــن موكلــي‬\n     ‫واملدعــى عليــه هــذا احلاضــر اتفــاق علــى أن يتاجــر املدعــى عليــه هــذا‬\n     ‫احلاضــر بهــذا املبلــغ يف الشــيء الــذي يــراه مناســب ًا ويكــون حــاال وعلــى‬\n     ‫أن تكــون األربــاح مناصفــة فمــن موكلــي رأس املــال ومــن املدعــى‬\n     ‫عليــه العمــل ومــن ذلــك التاريــخ وحتــى هــذا اليــوم وموكلــي لــم يســتلم‬\n     ‫أي شــيء ال مــن رأس املــال وال مــن األربــاح لــذا فموكلــي يطلــب إلــزام‬\n     ‫املدعــى عليــه بــأن يدفــع لــه مبلــغ اثنــن وأربعــن ألفــا وخمســمائة ريــال‬\n     ‫هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي اجــاب قائال كل‬\n     ‫مــا ذكــره املدعــي بالوكالــة يف دعــواه غيــر صحيــح والصحيــح بأنــه قــد‬\n     ‫جــرى بينــي وبــن خــال املدعــي اصالــة ويدعــى ‪ .....‬علــى أن يقــوم بتحويلي‬\n     ‫مبلــغ اثنــن وأربعــن ألفــا وخمســمائة ريــال ألســلمها ل‪ .....‬وهــو صاحــب‬\n     ‫مســاهمه وفعــا قــد وجــدت هــذا املبلــغ يف حســابي وقمــت بإيصالــه‬\n     ‫للشــخص املطلــوب ولــم يكــن بينــي وبــن املدعــي اصالــة أي اتفــاق بهــذا‬\n     ‫اخلصــوص ولــم يذكــر لــي ‪ .....‬عــن ذلــك أي شــيء وامنــا حســبت ان هــذا‬\n     ‫املبلــغ لــه خــاص حيــث ان بينــي وبــن املدعــي أصالــة مشــاكل أســريه‬\n     ‫مــن عــام ‪1419‬ه ـ وقــد كنــت اتالفــا التعامــل معــه لــذا أطلــب رد دعــوى‬\n     ‫املدعــي هكــذا أجــاب وبعــرض ذلــك علــى املدعــي بالوكالــة قــال كل‬\n     ‫مــا ذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا جــاء يف دعــواي‬\n     ‫هكــذا قــرر ثــم أبــرز املدعــي بالوكالــة ورقــة مكتــوب بعاليهــا حتويــل‬\n\n\n‫‪51‬‬\n\f‫مــن حســاب إلــى حســاب صــادرة مــن شــركة ‪ .....‬املصرفيــة لالســتثمار‬\n‫يف ‪1426/1/8‬ه ـ (اســم العميــل ‪ .....‬إلــى ‪ .....‬مبلــغ اثنــن وأربعــن ألفــا‬\n‫وخمســمائة ريــال )أ‪.‬ه ـ وبعــرض هــذه الورقــة علــى املدعــى عليــه قــال‬\n‫كل مــا جــاء يف هــذه الورقــة صحيــح وهنــاك تناقــض بــن دعــوى املدعــي‬\n‫وبــن التاريــخ املذكــور بالورقــة واطلــب ســؤال املدعــي بالوكالــة ملــاذا‬\n‫موكلــه حــول حلســابي وكيــف حصــل علــى رقــم حســابي هكــذا قــرر‬\n‫وبعــرض ذلــك علــى املدعــي بالوكالــة قــال أمــا بالنســبة للتناقــض بــن‬\n‫التاريخــن فالصحيــح مــا جــاء يف الورقــة وقــد أخطــأت يف التاريــخ‬\n‫املذكــور يف الدعــوى امــا بالنســبة ملــاذا موكلــي حــول حلســابه وذلــك‬\n‫لغــرض املتاجــرة امــا بالنســبة مــن أيــن حصــل موكلــي علــى رقم احلســاب‬\n‫فأطلــب املهلــة للرجــوع ملوكلــي هكــذا قــرر فجــرى ســؤال املدعــى عليــه‬\n‫هــل لديــك البينــة علــى دفعــك الــذي دفعــت بــه فقــال أطلــب املهلــة وأطلــب‬\n‫ا ســوف أقــوم للرجــوع‬     ‫حضــور ‪ .....‬هكــذا قــرر ثــم قــرر املدعــي قائ ـ ً‬\n‫ملوكلــي وســؤاله هــل لديــه البينــة أم ال هكــذا قــرر ثــم رفعــت اجللســة‬\n‫ويف هــذا اليــوم االحــد ‪1433/6/29‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n‫التاســعة صباحــا وفيهــا حضــر املدعــي بالوكالــة ‪ .....‬املدونــة هويتــه‬\n‫ووكالتــه يف اجللســة املاضيــة وحضــر حلضــوره املدعــى عليــه ‪ .....‬املدونــة‬\n‫هويتــه يف اجللســة املاضيــة ولــم يحضــر ‪ .....‬وقــد وردت الينــا إفــادة مــن‬\n‫قائــد دوريــات أمــن طريــق الباحــة برقــم ‪ 33/ .....‬يف ‪1433/4/11‬ه ـ‬\n‫واملتضمــن بــأن ‪ .....‬قــد تبلــغ بنفســه فجــرى ســؤال املدعــي بالوكالــة مــن‬\n‫أيــن حصــل موكلــك علــى رقــم حســاب املدعــى عليــه فقــال إن املدعــى‬\n‫عليــه هــو الــذي قــام بإعطــاء موكلــي رقــم حســابه بنفســه هكــذا قــرر‬\n‫وبعــرض ذلــك علــى املدعــى عليــه قــال كل مــا ذكــره غيــر صحيــح‬\n\n\n                                                                                      ‫‪52‬‬\n\f     ‫والصحيــح بأنــه قــد حصــل علــى رقــم حســابي مــن قبــل ‪ .....‬ألن بينــي‬\n     ‫وبينــه معامــات ماليــة وليــس بينــي وبينــه أي خــاف هكــذا قــرر ثــم‬\n     ‫قــرر املدعــي قائــا إن موكلــي يطلــب حضــور ‪ .....‬هكــذا قــرر فجــرى‬\n     ‫ســؤال املدعــى عليــه هــل أحضــرت البينــة علــى دفعــك الــذي دفعــت بــه‬\n     ‫فقــال ال بينــة لــدي اال اهلل عــز وجــل والــذي يعلــم الســر وأخفــى واطلــب‬\n     ‫ميــن املدعــي أصالــة هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــال ال مانع‬\n     ‫لــدي موكلــي مــن بــذل اليمــن واطلــب املهلــة إلحضــاره هكــذا قــرر‬\n     ‫ثــم رفعــت اجللســة ويف يــوم االثنــن املوافــق‪ 1434/02/11‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــى عليــه ‪ .....‬املدونــة‬\n     ‫هويتــه بعاليــه وحيــث ســبق ومت طلــب املدعــي أصالــة يف اجللســة املاضيــة‬\n     ‫حلضــور اجللســة يف هــذا اليــوم ألداء اليمــن علــى صحــة مــا يدعــي بــه‬\n     ‫كمــا مت طلــب املدعــو ‪ .....‬وقــد ورد إلينــا خطــاب رئيــس قســم محضــري‬\n     ‫اخلصــوم رقــم ‪ 331972144‬يف ‪1433/11/13‬ه املتضمــن إفــادة قائــد‬\n     ‫دوريــات أمــن الطــرق بالطائــف أنــه مت تبليــغ املذكــور وأفهــم باحلضــور‬\n     ‫يف املوعــد احملــدد ولــم يحضــر كمــا لــم يحضــر املدعــي أصالــة وال مــن‬\n     ‫ينــوب عنــه بوكالــة شــرعية عليــه فقــد أمــرت بشــطب املعاملــة للمــرة‬\n     ‫األولــى وحفظهــا باألرشــيف ويف هــذا اليــوم االثنــن ‪1434/04/22‬ه ـ‬\n     ‫افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي‬\n     ‫م‪ .....‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪ .....‬وقــد تقــدم باســتدعاء‬\n     ‫قيــد بهــذه احملكمــة برقــم ‪ 34/365242‬يف ‪1434/2/12‬ه ـ ويتضمــن‬\n     ‫اعتــذاره عــن تغيبــه عــن اجللســة احملــددة يف ‪1434/02/11‬ه ـ لظــروف‬\n     ‫عائليــة لديــه ولــم يحضــر املدعــى عليــه ‪ .....‬ولــم يردنــا مــا يفيــد بتبلغــه‬\n     ‫بهــذه اجللســة مــن عدمــه فعليــه وبنــاء علــى املــادة اخلامســة واخلمســن‬\n\n\n‫‪53‬‬\n\f‫مــن نظــام املرافعــات الشــرعية فقــد قــررت االســتمرار يف نظــر دعــوى‬\n‫املدعــي يف غيــاب املدعــى عليــه وبعــرض دعــوى املدعــي بالوكالــة علــى‬\n‫املدعــي أصالــة قــال كل مــا ادعــى بــه وكيلــي صحيــح هكــذا قــرر‬\n‫فجــرى ســؤاله هــل انــت مســتعد ببــذل اليمــن علــى صحــة دعــواك ونفــي‬\n‫مــا دفــع بــه املدعــى عليــه فقــال نعــم فجــرى نصحــه وتخويفــه بــاهلل عــز‬\n‫وجــل مــن مغبــة هــذه اليمــن اال أنــه أصــر فأذنــت لــه فحلــف قائــا واهلل‬\n‫العظيــم الــذي ال إلــه اال هــو املهلــك املــدرك بأنــه قــد جــرى بينــي وبــن‬\n‫املدعــى عليــه الغائــب عــن املجلــس الشــرعي ‪ .....‬اتفــاق علــى أن ادفــع لــه‬\n‫مبلــغ اثنــن واربعــن الفــا وخمســمائة ريــال علــى أن يتاجــر يف هــذا املــال‬\n‫ويضــارب بــه وتكــون االربــاح مناصفــة ولــم أقــل لــه ســلم هــذا املبلغ لــ‪.....‬‬\n‫ولــم يصلنــي مــن هــذا املبلــغ أي شــيء ال مــن االربــاح وال مــن رأس املــال‬\n‫واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n‫ومبــا أن دعــوى املدعــي قــد تضمنــت مطالبــة املدعــى عليــه بدفــع مبلــغ‬\n‫اثنــن واربعــن الفــا وخمســمائة ريــال وذلــك مبقابــل اتفــاق حاصــل‬\n‫بينهمــا علــى ان يكــون راس املــال مــن املدعــي والعمــل مــن املدعــى عليــه‬\n‫واالربــاح مناصفــة ومبــا أن املدعــى عليــه قــد دفــع بــأن هــذا املبلــغ قــد دفع‬\n‫ل‪ .....‬وذلــك بأمــر مــن املدعــي وإلقــرار املدعــى عليــه باســتالمه املبلــغ وال‬\n‫بينــة لديــه علــى دفعــه ولطلبــه ميــن املدعــي أصالــة وحلديــث املصطفــى‬\n‫صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن انكــر)‬\n‫وقــد قــرر العلمــاء قاعــدة بــأن علــى اليــد مــا أخــذت حتــى تؤديــه ومبــا‬\n‫أن املدعــي قــد بــذل اليمــن املطلوبــة جلميــع ذلــك فقــد ألزمــت املدعــى‬\n‫عليــه الغائــب عــن املجلــس الشــرعي ‪ .....‬بــأن يدفــع للمدعــي أصالــة ‪.....‬‬\n‫مبلــغ اثنــن واربعــن الفــا وخمســمائة ريــال وبــه حكمــت وبعرضــه علــى‬\n\n\n                                                                                         ‫‪54‬‬\n\f     ‫املدعــي قنــع بــه وأفهمتــه بــأن هــذا احلكــم حكــم حضــوري خاضــع‬\n     ‫لالســتئناف حســب التعليمــات وأمــرت بإصــدار صــك مبوجبــه وبعــث‬\n     ‫صــورة منــه للمدعــى عليــه لتقــدمي اعتــراض عليــه إن رغــب يف ذلــك يف‬\n     ‫مــدة ثالثــن يومــا مــن تاريــخ اســتالمه للحكــم جــرى التوقيــع وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n     ‫يف‪1434/04/22‬ه ـ الســاعة العاشــرة وخمســة واربعــن دقيقــة صباحــا‬\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫بالطائــف واخللــف لفضيلــة الشــيخ ‪ .....‬بالقــرار الصــادر مــن املجلــس‬\n     ‫األعلــى للقضــاء ذي الرقــم ‪ 34/1/77‬يف ‪1434/04/13‬ه ـ ويف هــذا‬\n     ‫اليــوم االثنــن ‪1434/7/10‬ه ـ جــرى االطــاع علــى هــذه املعاملــة وقــد‬\n     ‫وردتنــا الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه ‪ .....‬علــى احلكــم‬\n     ‫الصــادر مــن فضيلــة الشــيخ ‪ .....‬برقــم ‪ 34194620‬يف ‪1434/04/22‬ه ـ‬\n     ‫املقيــدة بهــذه احملكمــة برقــم ‪ 341649670‬يف ‪1434/07/09‬ه ـ وقــد‬\n     ‫قدمــت هــذه الالئحــة يف املــدة احملــددة نظامــا لالعتــراض وقــد انتقــل‬\n     ‫فضيلــة ناظــر القضيــة الشــيخ ‪ .....‬الــى العمــل باحملكمــة اجلزائيــة‬\n     ‫بالريــاض بقــرار معالــي وزيــر العــدل برقــم ‪ 10585‬يف ‪1434/04/21‬ه ـ‬\n     ‫فقــد جــرى بعثهــا الــى محكمــة االســتئناف مبكــة املكرمــة للتوجيــه‬\n     ‫مبــا يرونــه واهلل أســأل الســداد قــوال وعمــا وبــاهلل التوفيــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/10‬ه ـ‬\n                                             ‫الســاعة العاشــرة والنصــف صباحــا ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األحــد ‪1434/11/02‬ه ـ افتتحــت‬\n     ‫اجللســة يف متــام الســاعة الواحــدة والنصــف ظهــرا وفيهــا وردت املعاملــة‬\n     ‫مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 33108604‬يف‬\n\n\n‫‪55‬‬\n\f‫‪1434/07/30‬ه ـ ومرفــق بهــا قــرار الدائــرة احلقوقيــة األولــى رقــم‬\n‫‪ 34277481‬يف ‪1434/7/24‬ه ـ املتضمــن ( وبدراســة احلكــم وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقرر إعادتهــا إلى خلف فضيلة حاكمها‬\n‫إلرســال املعاملــة إلــى حاكــم القضيــة يف مقــر عملــه اجلديــد لالطــاع‬\n‫علــى الالئحــة االعتراضيــة متشــيا مــع املــادة ‪ 1/181‬واهلل املوفــق قاضــي‬\n‫اســتئناف ‪ .....‬قاضــي اســتئناف ‪ .....‬رئيــس الدائــرة ‪ .....‬واجلميــع ختمــه‬\n‫وتوقيعه)أ‪.‬ه ـ فجــرى إرســالها الــى فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بالريــاض وفقــا ملــا ورد يف قــرار محكمــة االســتئناف مبوجــب خطابنــا‬\n‫رقــم ‪ 33108604‬يف ‪1434/8/23‬ه ـ فوردنــا خطــاب فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض رقــم ‪ 342294287‬يف ‪1434/10/22‬ه ـ‬\n‫املتضمــن أنــه مت إكمــال الــازم علــى الصــك رقــم ‪ 34277481‬وتاريــخ‬\n‫‪1434/07/24‬ه ـ إلحلاقــه بضبطــه وســجله وباالطــاع علــى الصــك وجد‬\n‫إحلــاق فضيلتــه املتضمــن احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن‬\n‫‪1434/10/19‬ه ـ افتتحــت اجللســة يف متــام الســاعة الواحــدة والنصــف‬\n‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة رقــم‬\n‫‪ 34277481‬يف ‪1434/07/24‬هـ واملتضمن ما نصه ‪ :‬وبدراســة احلكم‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر إعادتهــا إلــى خلــف فضيلــة‬\n‫حاكمهــا إلرســال املعاملــة إلــى حاكــم القضيــة يف مقــر عمــاه اجلديــد‬\n‫لالطــاع علــى الالئحــة االعتراضيــة متشــيا مــع املــادة ‪ 1/181‬واهلل‬\n‫املوفــق قاضــي اســتئناف ‪ .....‬قاضــي اســتئناف ‪ .....‬رئيــس الدائــرة ‪.....‬‬\n‫واجلميــع ختمــه وتوقيعه)أ‪.‬ه ـ فعليــه أجيــب أصحــاب الفضيلــة مســتعينا‬\n‫بــاهلل عــز وجــل بأنــه قــد جــرى اطالعــي علــى الالئحــة االعتراضيــة‬\n‫املقدمــة مــن املدعــى عليــه ‪ .....‬واملقيــدة باحملكمــة العامــة بالطائــف‬\n\n\n                                                                                  ‫‪56‬‬\n\f     ‫برقــم ‪ 341649670‬يف ‪1434/07/09‬ه ـ واملكونــة مــن ورقــة واحــدة‬\n     ‫وباالطــاع عليهــا لــم أجــد بهــا مــا يؤثــر علــى مــا حكمــت بــه ولــذا‬\n     ‫فاحلكــم علــى حالــه وحــرر يف ‪1434/10/08‬ه ـ وصلــى اهلل علــى نبينــا‬\n     ‫محمــد القاضــي باحملكمــة اجلزائيــة بالريــاض ع‪ .....‬ختمــه وتوقيعــه )‬\n     ‫أ‪.‬ه ـ ولــذا فقــد أمــرت بإحلــاق ذلــك بضبطــه وســجله ورفعــة حملكمــة‬\n     ‫االســتئناف لتدقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/11/02‬ه ـ الســاعة الثانيــة ظهــرا ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف هــذا اليوم الثالثــاء ‪1434/12/17‬هـ افتتحت‬\n     ‫اجللســة يف متام الســاعة الثامنة وخمســة عشــر دقيقة صباحا وفيها وردت‬\n     ‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪342294287‬‬\n     ‫يف ‪1434/11/23‬ه ـ وقــد جــرى تدقيــق احلكــم مــن الدائــرة احلقوقيــة‬\n     ‫األولــى وصــدر بشــأنه القــرار رقــم ‪ 34362985‬يف ‪1434/11/19‬ه ـ‬\n     ‫واملــدون علــى ظهــر الصــك ونصــه ( احلمــد هلل وحــده وبعــد فقــد اطلعنــا‬\n     ‫علــى هــذا الصــك رقــم ‪ 34194620‬يف ‪1434/04/22‬ه ـ الصــادر‬\n     ‫مــن فضيلــة الشــيخ ‪ .....‬واصدرنــا القــرار رقــم ‪ 34362985‬وتاريــخ‬\n     ‫‪1434/11/19‬ه ـ املتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n     ‫واهلل املوفــق عضــو ‪ .....‬عضــو ‪ ....‬رئيــس الدائــرة ‪ .....‬واجلميــع ختمــه‬\n     ‫وتوقيعــه) أ‪.‬ه ـ فعليــه أمــرت بإحلــاق ذلــك بضبطــه وبســجله حتــى ال يخفى‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                 ‫حــرر يف ‪1434/12/17‬ه ـ الســاعة الثامنــة والنصــف صباحــا‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":49,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fc541671b2bfa6a0053a8a273ff3d42a198dcf62c6d7521e871a19249af0511b","normalized_text_hash":"8b277b6917c7b852977ea5bf22c95619018b1c4e9712e916c4deb7d9682dcbb3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p49-342294287"},{"id":"da889cad-c760-576d-9837-6c03eeff7b94","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة مبساهمة عقارية -مضاهاة التوقيع على سند املساهمة عن طريق األدلة اجلنائية -احلكم باليمن مع سند املساهمة املعتمدة من األدلة اجلنائية -احلكم بإعادة رأس املال دون األرباح .","document_number":"3462864","case_number":"31900253","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف يف هذا اليوم اإلثنن 1432/1/14ه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"شراكة مبساهمة عقارية -مضاهاة التوقيع على سند املساهمة عن طريق األدلة اجلنائية -احلكم باليمن مع سند املساهمة املعتمدة من األدلة اجلنائية -احلكم بإعادة رأس املال دون األرباح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/15 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3462864 :‬‬\n                              ‫الدعوى‪31900253 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34327285‬تاريخه‪1434/10/11 :‬هـ‬\n\n\n   ‫شــراكة مبســاهمة عقاريــة ‪ -‬مضاهــاة التوقيــع علــى ســند املســاهمة‬\n   ‫عــن طريــق األدلــة اجلنائيــة ‪-‬احلكــم باليمــن مــع ســند املســاهمة‬\n   ‫املعتمــدة مــن األدلــة اجلنائيــة ‪ -‬احلكــم بإعــادة رأس املــال دون األربــاح ‪.‬‬\n\n\n\n\n   ‫مــا ذكــره صاحــب كشــاف القنــاع ‪ :‬مــن أنــه البــد وأن يكــون املبيــع‬\n   ‫مملــوكا لبائعــه وقــت العقــد لقولــه صلــى اهلل عليــه وســلم حلكيــم بــن‬\n   ‫حــزام «ال تبــع مــا ليــس عنــدك» وقــال يف موضــع آخــر «والبــد أن يكــون‬\n   ‫املبيــع مقــدور ًا علــى تســليمه حــال العقــد ألن مــاال يقــدر علــى تســليمه‬\n                                     ‫شــبيه باملعــدوم واملعــدوم ال يصــح بيعــه» ‪.‬‬\n\n\n\n\n   ‫ادعــى املدعــي علــى املدعــى عليهمــا بأنه ســلم للمدعى عليــه األول مائتي‬\n   ‫ألــف ريــال يف ‪1426/6/10‬ه ـ مــن أجــل املســاهمة معــه ومــع شــريكه‬\n   ‫املدعــى عليــه الثانــي يف مخطــط مت بيــع املخطــط طلــب املدعــى الــزام‬\n   ‫املدعــى عليهمــا بدفــع رأس املــال واألربــاح انكــر املدعــى عليــه األول‬\n   ‫اســتالم املبلــغ وذكــر بــأن املســاهمة يف عــام ‪1423‬ه ـ وبيــع املخطــط يف‬\n   ‫عــام ‪1426‬ه ـ فكيــف حتصــل املســاهمة عنــد البيــع انكــر املدعــى‬\n   ‫عليــه الثانــي مــا جــاء يف دعــوى املدعــي أبــرز املدعــي ســند املســاهمة‬\n\n                                                                                        ‫‪58‬‬\n\f     ‫واســتالم املبلــغ املذكــور مــن قبــل املدعــى عليــه األول‪ ،‬أنكــر املدعــى‬\n     ‫عليــه األول هــذا الســند والتوقيــع املنســوب اليــه وذكــر بانــه مــزور ‪،‬‬\n     ‫مت بعــث الســند لألدلــة اجلائيــة ‪ ،‬ورد التقريــر بصحــة التوقيــع املنســوب‬\n     ‫للمدعــى عليــه األول ‪ ،‬حلــف املدعــى اليمــن علــى دعــواه مــن أن املدعــى‬\n     ‫عليــه األول اســتلم منــه املبلــغ املذكــور مــن أجــل املســاهمة املذكــورة ‪،‬‬\n     ‫قــرر املدعــى عليــه األول بــان األرض موضــع املســاهمة ثلثهــا لــه والثلثــان‬\n     ‫للمدعــى عليــه الثانــي وأن الصــك باســم املدعــى عليــه الثانــي ‪ ،‬تخلــف‬\n     ‫املدعــى عليــه الثانــي عــن احلضــور ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه‬\n     ‫األول بإعــادة رأس املــال للمدعــى البالــغ قــدره مائتــا الــف ريــال ‪ ،‬صــرف‬\n     ‫النظــر عــن دعــوى املدعــى باملطالبــة باألربــاح ‪ -‬اقتنــع املدعــى باحلكــم‬\n     ‫واعتــرض املدعــى عليــه األول ‪ -‬صــدق احلكــم مــن محكمة االســتئناف‬\n                                                                                      ‫‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة بالطائــف‬\n     ‫يف هــذا اليــوم اإلثنــن ‪1432/1/14‬ه ـ افتتحــت اجللســة بنــاء على اإلحالة‬\n     ‫الــواردة مــن فضيلــة الرئيــس برقــم ‪ 2/1376‬يف ‪1431/1/27‬ه ـ وفيهــا‬\n     ‫حضــر املدعــي‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم‪ ...‬كمــا حضــر‬\n     ‫املدعــى عليــه وكالــة‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم‪...‬‬\n     ‫بالوكالــة عــن املدعــى عليــه‪ ...‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بالطائــف برقــم ‪ 10315‬يف ‪1428/2/29‬ه ـ جلــد ‪ 2726‬ولــم يحضــر‬\n     ‫املدعــى عليــه‪ ...‬ولــم يــرد مــا يفيــد تبلغــه بهــذه اجللســة فســألت املدعــي‬\n     ‫عــن دعــواه قــال لقــد ســلمت املدعــى عليــه أصالــة‪ ...‬مبلــغ مائتــا ألــف ريــال‬\n\n‫‪59‬‬\n\f‫يف ‪1426/6/10‬ه ـ مســاهمة معــه ومــع شــريكه املدعــى عليــه الثانــي‪...‬‬\n‫يف املخطــط الواقــع ‪ ...‬علــى طريــق ‪ ...‬بجــوار قصــر‪ ...‬وقد مت بيع املخطط‬\n‫ولــم يســلمني املدعــى عليهــم رأس املــال واألربــاح لــذا أطلــب ســؤال‬\n‫املدعــى عليــه احلاضــر وإلــزام موكلــه واملدعــى عليــه‪ ...‬بدفــع رأس مالــي‬\n‫وقــدره مائتــا ألــف ريــال واألربــاح هــذه دعــواي وبعرضهــا علــى املدعــى‬\n‫عليــه وكالــة احلاضــر قــال مــا ذكــره املدعــي يف دعــواه غيــر صحيــح‬\n‫فموكلي لم يســتلم منه أي مبلغ للمســاهمة معه يف املخطط واملســاهمة‬\n‫كانــت عــام ‪1423‬ه ـ وبيــع املخطــط كان عام ‪1426‬هـ فكيف حتصل‬\n‫املســاهمة عنــد البيــع هكــذا أجــاب فســألته هــل موكلــه شــريك‪ ...‬يف‬\n‫املخطــط الــذي ذكــره املدعــي وأنهمــا فتــح فيــه مســاهمة قــال نعــم‬\n‫هكــذا أجــاب وبعــرض جوابــه علــى املدعــي قــال مــا ذكــره املدعــى‬\n‫عليــه وكالــة غيــر صحيــح والصحيــح مــا ذكرتــه يف دعــواي فســألته‬\n‫ألــك بينــة عليهــا قــال لــدي ســند موقــع مــن املدعــى عليــه ‪ ...‬وهــو ضمــن‬\n‫أوراق املعاملــة حيــث ســبق وأن بعثــه القاضــي ‪ ...‬لألدلــة اجلنائيــة لفحــص‬\n‫توقيــع املدعــى عليــه وقــد وجــد مــع أوراق املعاملــة خطــاب مديــر شــعبة‬\n‫األدلــة اجلنائيــة رقــم ‪ 3889‬يف ‪1432/5/13‬ه ـ ومشــفوعاته ســتة لفــات‬\n‫وظــرف مختــوم ويتضمــن مــا نصــه‪ :‬إشــارة إلــى كتابكــم رقــم‬\n‫‪ 32/68558‬بتاريــخ ‪1432/5/1‬ه ـ بشــأن دعــوى املدعــو ‪ ...‬ضــد ‪...‬‬\n‫وطلبكــم إجــراء الفحــص الفنــي لتوقيــع املدعــى عليــه عليــه نفيدكــم‬\n‫بأنــه جــرى االتصــال علــى املدعــى عليــه املدعــو ‪ ...‬املذكــور عــدة مــرات‬\n‫إال أنــه لــم يجــب علــى املكاملــات الصــادرة مــن قبلنــا أ‪.‬ه ـ وقــد وجــد مــع‬\n‫لفــات هــذه األوراق ورقــة هــذا نصهــا‪ :‬بســم اهلل الرحمــن الرحيــم عقــد‬\n‫مســاهمة أقــر أنــا ‪ ...‬أننــي قــد اســتلمت مبلــغ ‪ 200000‬فقــط مائتــان ألــف‬\n\n\n                                                                                       ‫‪60‬‬\n\f     ‫ريــال ســعودي ال غيــر مــن املدعــو ‪ ...‬رقــم ‪ 1021‬يف ‪1398/7/19‬ه ـ‬\n     ‫مصدرهــا عفيــف عبــارة عــن مســاهمة يف األرض الواقعــة علــى طريــق‬\n     ‫مكــة بجــوار قصــر ‪ ....‬باســم ‪ ...‬الــذي معــد للتخطيــط صــدر هــذا العقــد‬\n     ‫بتاريــخ ‪1426/6/10‬ه ـ الطــرف األول ‪ ...‬توقيعــه الطــرف الثانــي ‪...‬‬\n     ‫توقيعــه أ‪.‬ه ـ وقــال املدعــي هــذا هــو الســند الــذي ذكــرت وبعــرض هــذا‬\n     ‫الســند علــى املدعــى عليــه وكالــة قــال غيــر صحيــح هــذا الســند وتوقيــع‬\n     ‫موكلــي عليــه غيــر صحيــح وهــو مــزور وســبق وأن بعثــه القاضــي ‪ ...‬بعــد‬\n     ‫أن أخــذ توقيــع موكلــي يف ورقــة أخــرى فجــرى عرض مــا ورد يف خطاب‬\n     ‫األدلــة اجلنائيــة عليــه قــال بأنهــم لــم يطلبــوا موكلــي ومســتعد باحلضــور‬\n     ‫إذا طلبــوا هكــذا أجــاب فجــرى ســؤال املدعــي هــل لديــه زيــادة بينــة قــال‬\n     ‫ســأبحث عــن زيــادة بينــة لــذا ولطلــب املدعــى عليهمــا أصالــة رفعــت‬\n     ‫اجللســة ويف جلســة أخــرى لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة‬\n     ‫بالطائــف وفيهــا حضــر املدعــي ‪ ...‬كمــا حضــر حلضــوره املدعــى عليــه‬\n     ‫وكالــة ‪ ...‬مبوجــب الوكالــة عــن ‪ ...‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بالطائــف برقــم ‪ 35699‬وتاريــخ ‪1432/7/11‬ه ـ جلــد ‪5236‬املخولــه لــه‬\n     ‫املدافعــة واملرافعــة واالقــرار واالنــكار كمــا حضــر املدعــى عليــه‬\n     ‫وكالــة ‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ...‬بالوكالــة عــن ‪...‬‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف برقــم ‪ 52628‬يف‬\n     ‫‪1432/10/28‬ه ـ جلــد ‪ 5406‬املخولــه لــه املدافعــة واملرافعــة واالقــرار‬\n     ‫واالنــكار وبســؤال املدعــى عليــه وكالــة ‪ ....‬عــن عــدم حضــور موكلــه‬\n     ‫يف هــذه اجللســة فقــال إن موكلــي مســتعد باحلضــور يف اجللســة القادمــة‬\n     ‫وأفهمتــه بأنــه إذا لــم يحضــر فلــن تقبــل مرافعتــه عــن موكلــه وبســؤال‬\n     ‫املدعــى عليــه وكالــة ‪ ...‬عــن دعــوى املدعــي فأجــاب بــأن مــا ذكــره‬\n\n\n‫‪61‬‬\n\f‫املدعــي يف دعــواه غيــر صحيــح فموكلــي ليــس بينه وبني ‪ ...‬أي شــراكة‬\n‫يف املخطــط محــل الدعــوى ثــم أضــاف بــأن موكلــه يطالــب املدعــى‬\n‫عليــه ‪ ...‬باســتحقاقات ماليــة مقدارهــا ثمانيــة ماليــن ريــال وذلــك يف‬\n‫شــراكة بينهمــا يف مخطــط يف جــدة وبســؤاله هــل ملوكلــه مخططــات‬\n‫يف الطائــف بشــراكة املدعــى عليــه ‪ ...‬فقــال أنــا ال اســتطيع اإلجابــة عــن‬\n‫هــذا وأطلــب مهلــة يف ذلــك هكــذا قــال وبعــرض جــواب وكيــل املدعــى‬\n‫عليــه ‪ ...‬علــى املدعــي فقــال مــا ذكــره املدعــى عليــه غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه يف دعــواي هكــذا أجــاب لــذا فقــد جــرى رفــع‬\n‫اجللســة وذلــك حلضــور املدعــى عليــه أصالــة ‪ ...‬واملدعــى عليــه أصالــة ‪...‬‬\n‫ويف جلســة أخــرى وفيهــا حضــر املدعــي ‪ ...‬كمــا حضــر حلضــوره املدعــى‬\n‫عليــه أصالــة ‪ ...‬ســجل مدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه ‪ ...‬وال مــن‬\n‫ميثلــه بوكالــة شــرعية وقــد وردنــا خطــاب يتضمــن طلــب إعتــذار عــن‬\n‫حضور اجللسة من املدعي عليه أصالة واحملال إلينا برقم ‪331868809‬‬\n‫يف ‪1433/10/23‬ه ـ وقــد تضمــن إعتــذاره عــن اجللســة احملــددة يف هــذا‬\n‫اليــوم وذلــك لوجــود زواج يخصــه يف هــذا التاريــخ باملدينــة املنــورة كمــا‬\n‫تعهــد بإســتالم موعــد اجللســة األخــرى علــى اجلــوال املدون رقمــه باخلطاب‬\n‫ثــم جــرى مناقشــة املدعــى عليــه احلاضــر عــن جــواب وكيلــه عــن الدعوى‬\n‫فصــادق علــى مــا ذكــره وكيلــه يف جوابــه علــى دعــوى املدعــي وأبــرز‬\n‫ورقــة وطلــب رصــد مضمونهــا وهــي كاآلتــي أن املدعــي ذكــر يف‬\n‫صحيفــة الدعــوى بأنــه ســلمني مبلــغ وقــدره مائتــا ألــف ريــال وهــي عبــارة‬\n‫عــن مســاهمة يف مخطــط ‪ ...‬مبوجــب عقــد بينــه وبينــي بتاريــخ‬\n‫‪1426/6/10‬ه ـ قــدم بهــا ورقــة وليــس عقــد معنــون بعقــد مســاهمة وهــي‬\n‫‪1‬ـ بــدون شــروط ‪2‬ـ بــدون شــهود ‪3‬ـ بــدون هويــة ســوى هويتــه وتوقيعــه ‪4‬ـ‬\n\n\n                                                                                      ‫‪62‬‬\n\f     ‫تفقــد كامــل املصداقيــة ‪5‬ـ ذكــر يف ورقــة العقــد املزعومــه املســاهمة‬\n     ‫وقــت البيــع ووقــت قبــض الثمــن حســب زعمــه بــد ًال مــن املســاهمة وقــت‬\n     ‫الشــراء وأن مــا قــام بــه مــن دعــوى زائفــة لضيــاع حــق مشــروع وثابــت‬\n     ‫وموثــق بوثائــق رســمية بينــه وبــن ‪ ...‬ويقــر بهــا شــريكه ‪ ...‬وأن املخطــط‬\n     ‫املتصــرف بــه صاحبــه يعطــي مــن يســفط لــه ولــم يفتــح مســاهمة ملــن أراد‬\n     ‫املســاهمة حتــى يضــع موكلــي وســيط ًا بينهمــا فنأمــل منكــم التأكــد‬\n     ‫ـواء بإحضــار شــريكه ‪ ...‬للتأكــد مــن مطالبــة ‪ ...‬لــه‬   ‫ممــا ذكــرت سـ ً‬\n     ‫ول‪ ...‬الــذي يزعــم بهــذه الدعــوى الكيديــة لضيــاع احلــق الثابــت وإرســال‬\n     ‫الورقــة إلــى اجلهــات املختصــة هــذا مــا تضمنتــه ورقــة املدعــى عليــه ‪...‬‬\n     ‫التــي أبرزهــا وقــد مت ضمهــا ضمــن أوراق املعاملــة كمــا وردنــا خطــاب‬\n     ‫مديــر شــركة محافظــة الطائــف واملعطــوف علــى خطــاب فضيلــة‬\n     ‫القاضــي ‪ ...‬برقــم ‪5588‬ع يف ‪1433/6/18‬ه ـ واملتضمــن عليــه نفيدكــم‬\n     ‫بــأن أوراق مضاهــات توقيــع ‪ ...‬املذكــور رفعــت ملعالــي محافــظ الطائــف‬\n     ‫وذلــك لطلبنــا أســاس عقــد فتــح حســابه ومــا يحتويــه مــن مســتندات‬\n     ‫بنكيــة ليتمكــن مــن الفحــص واملضاهــاه ولــم تردنــا اإلجابــة حتــى‬\n     ‫تاريخــه لــذا ولكتابــة خطــاب إحلاقــي لشــرطة محافظــة الطائف لفحص‬\n     ‫توقيــع املدعــى عليــه ‪ ...‬لــذا فقــد جــرى رفــع اجللســة وبــاهلل التوفيــق ويف‬\n     ‫جلســة أخــرى لــدي أنــا ‪ ...‬مســاعد رئيــس احملكمــة العامــة بالطائــف‬\n     ‫القائــم بعمــل املكتــب القضائــي احلــادي عشــر وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف املســاعد‬\n     ‫برقــم ‪ 31900253‬وتاريــخ ‪ 1431/11/17‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 315723‬وتاريــخ ‪1431/11/17‬ه ـ ففــي يــوم الســبت املوافــق‬\n     ‫‪1434/02/02‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية‬\n\n\n‫‪63‬‬\n\f‫مبوجــب الســجل املدنــي رقــم ‪ ...‬كمــا حضــر حلضــوره كال مــن املدعــى‬\n‫عليــه أصالــة ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫واملدعــى عليــه وكالــة ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ...‬بوكالتــه عــن ‪ ...‬بالوكالــة رقــم ‪ 52628‬يف ‪1432/10/28‬ه ـ اجللــد‬\n‫‪ 5406‬واملتضمنــة إقامــة وســماع عمــوم الدعــاوى واملطالبــات واملدافعــة‬\n‫واملرافعــه وحضــور اجللســات وتقــدمي البينــات واالقــرار واالنــكار و قبول‬\n‫االحــكام و نفيهــا واالعتــراض عليهــا و طلــب االميــان و االســتالم و‬\n‫التســليم وبســؤالهم عــن األوراق اخلاصــة مبضاهــاة التوقيــع لــدى إدارة‬\n‫األدلــة اجلنائيــة فأفــاد املدعــي ‪ ...‬بأنهــا ال زالــت لــدى إدارة األدلــة اجلنائيــة‬\n‫و أنهــا ســوف ترســل إلــى احملكمــة خــال األســبوع القــادم وحلــن ورود‬\n‫اجلــواب رفعــت اجللســة ويف جلســة اخــرى لــدي أنــا ‪ ...‬القاضــي باحملكمــة‬\n‫العامــة بالطائــف أفتتحــت اجللســة وفيهــا حضــر املدعي أصالــة ‪ ...‬وحضر‬\n‫حلضــور املدعــى عليــه أصالــة ‪ ...‬واملدعــى عليــه وكالــة ‪ ...‬وقــد وردتنــا‬\n‫إفــادة مديــر األدلــة اجلنائيــة املقيــدة باحملكمة برقــم ‪ 34439492‬وتاريخ‬\n‫‪1434/2/23‬ه ـ واملرفــق بهــا التقريــر الفنــي إلدارة الفحوصــات الفنيــة‬\n‫للتزييــف والتزويــر رقــم ‪ 33781‬ومضمونــه الفحــص والنتيجــة مبضاهــاة‬\n‫التوقيــع الثابــت بالعقــد موضــع الفحــص علــى توقيــع املدعــو ‪ ...‬الثابــت‬\n‫بــاألوراق املرســلة للمضاهــاة وجدنــا أنهمــا يتفقــان الفاحــص ‪ ...‬توقيعــه‬\n‫اخلبيــر ‪ ...‬توقيعــه مديــر شــعبة اخلطــوط والتواقيــع ‪ ...‬توقيعــه مديــر إدارة‬\n‫الفحــوص الفنيــة للتزييــف والتزويــر ‪ ...‬توقيعــه أ‪.‬ه ـ وبســؤال املدعــي هــل‬\n‫يســتطيع حلــف اليمــن علــى أنــه ســلم املدعــى عليــه ‪ ...‬املبلــغ املدعــى بــه‬\n‫والــذي قــدره مائتــي ألــف ريــال فقــال نعــم فأذنــت لــه يف حلــف اليمــن‬\n‫ا بعــد تخويفــه مــن عاقبــة اليمــن الكاذبــه واهلل الــذي الإلــه‬      ‫فحلــف قائـ ً‬\n\n\n                                                                                             ‫‪64‬‬\n\f     ‫غيــره وال رب ســواه أنــي ســلمت املدعــى عليــه هــذا احلاضــر ‪ ...‬مبلــغ‬\n     ‫وقــدره مائتــي ألــف ريــال عبــارة عــن مســاهمة يف األرض الواقعــة علــى‬\n     ‫طريــق مكــة بجــوار قصــر ‪ ...‬ولــم يعــد لــي مــن املبلــغ أي شــيء واهلل‬\n     ‫العظيــم هكــذا حلــف وبســؤال املدعــي واملدعــى عليهمــا هــل لديهمــا‬\n     ‫اضافــة علــى ماذكــروه فقــال املدعــى عليــه ‪ ...‬بــأن لديــه صــك برقــم‬\n     ‫‪ 1/3/186/144‬وتاريــخ ‪1423/7/17‬ه ـ علــى األرض التــي يدعــي فيهــا‬\n     ‫املدعــي بأنــه مســاهم فيهــا وأنــا و‪ ...‬قــد اشــترينا األرض مــن وكيــل ‪...‬‬\n     ‫وأن لــي مــن األرض ثلــث ولــ‪ ...‬الثلثــن هكــذا أضــاف ثــم اضاف املدعي‬\n     ‫بأنــه يطالــب بــرأس املــال واألربــاح ثــم جــرى ســؤال املدعــى عليــه ‪ ...‬هــل‬\n     ‫صــك املخطــط باســمه أو باســم ‪ ...‬فقــال بــأن الصــك الــذي يدعــي فيــه‬\n     ‫ـاء علــى ماتقــدم مــن الدعــوى‬  ‫املســاهمة باســم ‪ ...‬هكــذا قــرر فبنـ ً‬\n     ‫واإلجابــة وملــا ورد يف التقريــر الفنــي رقــم ‪ 33781‬وملــا ورد يف عقــد‬\n     ‫املســاهمة احملــرر يف ‪1426/6/10‬ه ـ وملــا ذكــره صاحــب كشــاف‬\n     ‫القنــاع (مــن أنــه ال بــد وأن يكــون املبيــع مملــوك ًا لبائعــه وقــت العقــد‬\n     ‫لقولــه صلــى اهلل عليــه وســلم حلكيــم بــن حــزام «التبــع ماليــس عنــدك»‬\n     ‫وقــال مانصــه يف موضــع آخــر والبــد أن يكــون املبيــع مقــدور ًا علــى‬\n     ‫تســليمه حــال العقــد ألن مــاال يقدر على تســليمه شــبيه باملعــدوم واملعدوم‬\n     ‫اليصــح بيعــه») إذا فنــص البهوتــي يف الكشــاف ينســحب علــى هــذه‬\n     ‫الدعــوى حيــث أن هــذه املســاهمة باطلــة لعــدم ثبــوت الشــراكة حيــث‬\n     ‫إن املدعــى عليــه ‪ ...‬قــد أقــر بــأن صــك األرض باســم ‪ ...‬واإلقــرار حجــة‬\n     ‫موجبــة بنفســه وحللــف املدعــي اليمــن التــي طلبــت منــه لذلــك كلــه فقــد‬\n     ‫حكمــت علــى املدعــى عليــه ‪ ......‬بدفــع مبلــغ وقــدره مائتــي ألــف ريــال‬\n     ‫للمدعــي ‪ ...‬كمــا حكمــت بصــرف النظــر عــن مطالبــة املدعــى باألرباح‬\n\n\n‫‪65‬‬\n\f‫يف مســاهمته وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة وأمــا‬\n‫املدعــى عليــه ‪ ...‬قــرر عــدم القناعــة باحلكــم وطلــب االســتئناف وأفهــم‬\n‫بــأن عليــه تقــدمي الالئحــة االعتراضيــة خــال ثالثــن يومــا مــن اســتالم‬\n‫احلكــم وإذا لــم يتقــدم خــال هــذه املــدة فــإن حقــة يف اإلعتــراض يســقط‬\n‫ويكتســب احلكــم الصفــة القطعيــة ففهــم ذلــك وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/03/03‬هـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق‪1434/09/09‬‬\n‫ه ـ افتتحــت اجللســة يف متــام الســاعة الواحــدة ظهــرا وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بخطــاب فضيلــة رئيســها رقــم ‪341125782‬‬\n‫يف ‪1434/8/2‬ه ـ واملرفــق بــه قــرار مالحظــة الدائــرة احلقوقيــة الســابعة‬\n‫رقمــه ‪ 34282162‬يف ‪1434/7/29‬ه ـ واملتضمــن أنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫إلكمــال الــازم علــى قرارنــا رقــم ‪ 34222419‬يف ‪1434/5/26‬ه ـ‬\n‫مبوجــب املــادة ‪ 1/187‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أه ـ وباالطــاع علــى قــرار املالحظــة ذي الرقــم ‪34222419‬‬\n‫يف ‪1434/5/26‬ه ـ واملتضمــن أنــه وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا إلكمــال الــازم‬\n‫فيمــا ســبق رصــده لــدى ســلفه مبوجــب املــادة ‪ 166‬مــن نظــام املرافعــات‬\n‫الشــرعية ثــم إعــادة املعاملــة لتتــم الدراســة واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ‪ ...‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه‬\n\n\n                                                                                    ‫‪66‬‬\n\f     ‫وتوقيعــه أه ـ عليــه أجيــب أصحــاب الفضيلــة قضــاة االســتئناف بأنــه مت‬\n     ‫إكمــال الــازم وإرفــاق مــا مت طلبــه بصــورة الضبــط لــذا فقــد قــررت‬\n     ‫إعــادة املعاملــة حملكمــة االســتئناف حســب املتبــع وبــاهلل التوفيــق‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n                                                                 ‫يف ‪1434/9/9‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالطائــف وحيــث رفعــت املعاملــة إلــى محكمــة االســتئناف وعــادت منهــا‬\n     ‫مصدقــة بالقــرار رقــم ‪ 34327285‬يف ‪1434/10/11‬ه ـ الصــادر مــن‬\n     ‫الدائــرة احلقوقيــة الســابعة واملتضمــن بعــد املقدمــة مــا نصــه (وبدراســة‬\n     ‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n     ‫احلكم)أ‪.‬هـ‪.‬لــذا جــرى إحلاقــه وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/2‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ‬\n     ‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n     ‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪341125782‬‬\n     ‫وتاريــخ ‪1434/09/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n     ‫‪ ...‬القاضــي باحملكمــة العامــة بالطائــف املســجل برقــم ‪ ...‬وتاريــخ‬\n     ‫‪1434/03/15‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬و‪ ، ...‬وبدراســة الصــك‬\n     ‫وص ــورة ضبط ــه والئحتــه اإلعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪.‬‬\n     ‫واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه‬\n                                                                    ‫و ســلم‪،،،،،‬‬\n\n\n\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":58,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e7ff12f69925acb7ec725a97d2942bd34aeb6b4f87fa65ff69de761c64ed9b0","normalized_text_hash":"898141834c3bfc8a13bdcba6785e0e125df3120a8ac16196cfa1883a7ca6f1cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p58-3462864"},{"id":"00cc2eac-f789-5e45-9291-b3f298d91e47","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -مضاربة -العامل أمن يف مال املضاربة -القول قول العامل يف عقد املضاربة يف الربح واخلسارة مع ميينه -القول قول العامل يف نوع التجارة مع ميينه -سند قبض مبلغ املضاربة -بينة غير موصلة -القضاء باليمن .","document_number":"3458957","case_number":"32182838","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"شراكة -مضاربة -العامل أمن يف مال املضاربة -القول قول العامل يف عقد املضاربة يف الربح واخلسارة مع ميينه -القول قول العامل يف نوع التجارة مع ميينه -سند قبض مبلغ املضاربة -بينة غير موصلة -القضاء باليمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/9 :‬هـ َر ْق ُم‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3458957 :‬‬\n                             ‫الدعوى‪32182838 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34233074‬تاريخه‪1434/6/6:‬هـ‬\n\n\n ‫شــراكة ‪ -‬مضاربــة ‪ -‬العامــل أمــن يف مــال املضاربــة ‪ -‬القــول قــول‬\n ‫العامــل يف عقــد املضاربــة يف الربــح واخلســارة مــع ميينــه ‪ -‬القــول قــول‬\n ‫العامــل يف نــوع التجــارة مــع ميينــه ‪ -‬ســند قبــض مبلــغ املضاربــة ‪ -‬بينــة‬\n                                         ‫غيــر موصلــة ‪ -‬القضــاء باليمــن ‪.‬‬\n\n\n\n\n ‫‪ -1‬مــا رواه البيهقــي عــن ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل‬\n ‫صلــى اهلل عليــه وســلم قــال‪( :‬لــو يعطــى النــاس بدعواهــم الدعــى رجــال‬\n ‫أمــوال قــوم ودماءهــم لكــن البينــة علــى املدعــى واليمــن علــى مــن أنكر)‪.‬‬\n ‫‪ -2‬قــال يف كشــاف القنــاع (‪( :)524/8‬والعامــل أمــن يف مــال املضاربــة)‬\n ‫ثــم قــال‪( :‬والقــول قولــه يف قــدر رأس املــال والربــح وأنــه ربــح أو لــم يربــح‬\n ‫وفيمــا يدعيــه مــن هــاك أو خســران) وقــال أيضـ ًا (‪( :)457/8‬أو اختلفــا‬\n ‫أي الوكيــل واملضــارب مــع رب املــال يف صفــة اإلذن يف الوكالــة أو‬\n ‫املضاربــة فقولهمــا أي الوكيــل واملضــارب بيمينهمــا ألنهمــا أمينــان يف‬\n                                                 ‫التصــرف فقبــل قولهمــا)‪.‬‬\n\n\n\n\n ‫ادعــت املدعيــة علــى املدعــى عليــه بأنهــا دفعــت لــه مائــة ألــف ريــال‬\n ‫ليقــوم باســتثمارها وتكــون األربــاح بينهمــا مناصفــة ‪ -‬واتفقــت معــه‬\n\n                                                                                          ‫‪68‬‬\n\f     ‫علــى أن يكــون النشــاط يف جتــارة اخلضــار والفواكــه أو يف مجــال‬\n     ‫ســيارة األجــرة بحيــث يشــتري ســيارة أجــرة ويكــون ســائق ًا لهــا ‪ -‬وأنــه‬\n     ‫لــم يســلمها مــن رأس املــال وال األربــاح شــيئ ًا ‪ -‬كمــا أقرضتــه ثمانيــة‬\n     ‫آالف وثمامنائــة وثمانــن ريــا ًال ولــم يســدد هــذه القــرض ‪ -‬طلبــت املدعيــة‬\n     ‫إلــزام املدعــى عليــه بإعــادة هذيــن املبلغــن ‪ -‬أقــر املدعــى عليــه باســتالم‬\n     ‫املائــة ألــف ريــال مــن أجــل املتاجــرة بهــا وأن املدعيــة لــم حتــدد لــه‬\n     ‫نشــاط ًا معينــا‪ -‬وأنــه تاجــر بهــا باألســهم وخســر اثنــن وعشــرين ألــف‬\n     ‫ريــال واقتــرض منهــا املبلــغ املتبقــي ســبعة وثالثــن ألــف ريــال ‪ -‬أمــا مــا‬\n     ‫يتعلــق باملبلــغ الثانــي فذكــر املدعــى عليــه أنــه لــم يقتــرض هــذا املبلــغ‬\n     ‫وأن هــذا املبلــغ ميثــل قيمــة هدايــا قدمتهــا املدعيــة باســم ابنــه يف حفــل‬\n     ‫إحــدى الروضــات التــي كان يــدرس بهــا‪ -‬أنكــرت املدعيــة هــذا الدفــع‬\n     ‫وذكــرت بــأن الصحيــح مــا جــاء يف دعواهــا ‪ُ -‬طلــب مــن الطرفــن البينــة‬\n     ‫علــى مــا ذكــرا فلــم يحضــرا بينــة ‪ -‬حلــف املدعــى عليــه اليمــن علــى‬\n     ‫أن املدعيــة لــم حتــدد لــه نــوع النشــاط التجــاري للمائــة ألــف وأنــه تاجــر‬\n     ‫بهــا يف األســهم وأنــه خســر اثنــن وعشــرين ألــف ريــال واملتبقــي ثمانيــة‬\n     ‫وســبعون ألــف ريــال وأنــه لــم يقتــرض منهــا املبلــغ الثانــي وقــدره ثمانيــة‬\n     ‫آالف وثمامنائــة وثمانــون ريــا ًال ولــم يطلــب منهــا أو يفوضهــا يف ســدادها‬\n     ‫عنــه وال شــراء قيمــة هدايــا وال غيرهــا ‪ -‬كمــا حلفــت املدعيــة أنهــا لــم‬\n     ‫تهــب املدعــي عليــه واحــد ًا وأربعــن ألــف ريــال ‪ -‬صــدر احلكــم بإلــزام‬\n     ‫املدعــى عليــه بــأن يدفــع للمدعيــة ثمانيــة وســبعني ألــف ريــال وصــرف‬\n     ‫النظــر عمــا زاد عــن ذلــك ‪ -‬قــرر الطرفــان عــدم القناعــة ‪ -‬صــدق احلكم‬\n                                                          ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫‪69‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫جدة‪/‬املســاعد برقــم ‪ 32182838‬وتاريــخ ‪ 1432/05/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32571902‬وتاريــخ ‪ 1432/05/20‬ه ـ حضــرت ‪...‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر حلضورهــا ‪...‬‬\n‫‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ...‬فادعــت ‪ ....‬قائلــة يف دعواهــا‬\n‫لقــد دفعــت للمدعــى عليــه مبلغ ـ ًا وقــدره مائــة ألــف ريــال كــي يقــوم‬\n‫باســتثمارها وتكــون األربــاح بيننــا مناصفــه وقــد اتفقــت معــه علــى أن‬\n‫يكــون النشــاط يف أحــد أمريــن إمــا يف جتــارة اخلضــار والفاكهــة أو‬\n‫يف مجــال ســيارة أجــرة بحيــث يشــتري ســيارة أجــرة ويكــون ســائق ًا‬\n‫لهــا ولكنــه لــم يســلمني شــيئ ًا مــن رأس املــال واألربــاح حتــى اآلن كمــا‬\n‫أنــي أقرضتــه مبلغـ ًا وقــدرة ثمانيــة آالف وثمامنائــة وثمانــون ريــا ًال قرضـ ًا‬\n‫حســن ًا ولــم يعــده لــي أطلــب إلزامــه بــأن يعيــد لــي رأس املــال واملبلــغ الــذي‬\n‫أقرضتــه لــه ومجمــوع ذلــك مبلــغ وقــدره مائــة وثمانيــة آالف وثمامنائــة‬\n‫وثمانــون ريــا ًال هكــذا ادعــت وبعــرض الدعــوى علــى املدعــى عليــه‬\n‫قــال مــا ذكرتــه املدعيــة يف دعواهــا مــن أنهــا أعطتنــي مبلغ ـ ًا وقــدره‬\n‫مائــة ألــف ريــال فهــو صحيــح ومــا ذكرتــه مــن أن النشــاط يكــون يف‬\n‫مجــال اخلضــار والفواكــه أو يف مجــال ســيارة أجــرة فهــو غيــر صحيــح‬\n‫والصحيــح أننــا لــم نتفــق علــى نشــاط معــن ثــم طلــب املدعــى عليــه مهلــة‬\n‫لتحريــر إجابتــه ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهــا مــن‬\n\n                                                                                            ‫‪70‬‬\n\f     ‫قبــل اخيهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر‬\n     ‫حلضــوره املدعــى عليــه وكالــة ‪ ...‬بالوكالــة عــن ‪ ...‬مبوجــب الوكالــة‬\n     ‫رقــم ‪ 15897‬يف ‪ 1433/02/17‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بشــمال محافظــة جــدة وقــد أبــرز مذكــرة مكونــة مــن صفحتــن‬\n     ‫ذكــر أنهــا تشــتمل علــى االجابــة علــى الدعــوى وباالطــاع عليهــا وجــد‬\n     ‫أنهــا تتضمــن إقــرار املدعــى عليــه باســتالم مبلــغ وقــدره مائــة ألــف ريــال‬\n     ‫وأن املدعيــة عندمــا ســلمته املبلــغ لــم يتــم االتفــاق علــى نشــاط معــن‬\n     ‫فقــام املدعــى عليــه باملضاربــة بهــا يف ســوق األســهم فخســر مبلغــا‬\n     ‫وقــدره اثنــان وعشــرون ألــف ريــال ثــم طلــب املدعــى عليــه مــن املدعيــة‬\n     ‫ان تقرضــه مــن املبلــغ املتبقــي ‪ -‬وقــدره ثمانيــة وســبعون الــف ريــال‬\n     ‫‪ -‬مبلغــا وقــدره ســبعة وثالثــون ألــف ريــال فوافقــت فتبقــى مــن املبلــغ‬\n     ‫مبلغـ ًا وقــدره واحــد وأربعــون ألــف ريــال فوهبتــه املدعيــة للمدعــى عليــه‬\n     ‫وأمــا مــا يتعلــق باملبلــغ الــذي قــدره ثمانيــة آالف وثمامنائــة وثمانــون ريــاال‬\n     ‫الــذي تدعــي املدعيــة أنهــا أقرضتــه للمدعــى عليــه فهــو غيــر صحيــح‬\n     ‫والصحيــح أن هــذا املبلــغ ميثــل قيمــة هدايــا قدمتهــا املدعيــة باســم ابــن‬\n     ‫املدعــى عليــه يف حفــل إحــدى الروضــات التــي كان يــدرس فيهــا ولــم‬\n     ‫يطلــب موكلــي ذلــك منهــا ولــم يفوضهــا بذلــك فيكــون املبلــغ املتبقــي‬\n     ‫بذمــة موكلــي مبلغــا وقــدره ســبعة وثالثــون ألــف ريــال وهــو مســتعد‬\n     ‫بدفعــه هــذا ملخــص مــا جــاء يف املذكــرة وقــد جــرى إرفاقهــا يف‬\n     ‫املعاملــة وبعــرض ذلــك علــى املدعيــة قالــت بــل الصحيــح مــا ذكرتــه‬\n     ‫يف دعــواي هكــذا أجابــت فجــرى ســؤالها هــل لديهــا بينــة تثبت صحة‬\n     ‫دعواهــا مــن أن النشــاط املتفــق علــى املضاربــة فيــه هــو بيــع اخلضــروات‬\n     ‫والفواكــه أو ســيارة أجــرة وأنهــا أقرضــت املدعــى عليــه أصالــة املبلــغ‬\n\n\n‫‪71‬‬\n\f‫الــذي قــدره ثمانيــة آالف وثمامنائــة وثمانــون ريــاال فقالــت ليــس لــدي‬\n‫بينــة علــى ذلــك هكــذا أجابــت ثــم جــرى ســؤال املدعــى عليــه وكالــة‬\n‫هــل لــدى موكلــه بينــة تثبــت أن املدعيــة قــد وهبتــه مــن املتبقــي مــن‬\n‫مــال املضاربــة مبلغــا وقــدره واحــد وأربعــون ألــف ريــال فقــال ليــس لــدى‬\n‫موكلــي بينــة علــى ذلــك هكــذا أجــاب وقــد أبــرزت املدعيــة ثالثــة‬\n                ‫ســندات موقعــة بتوقيــع منســوب للمدعــى عليــه تتضمــن ‪:‬‬\n‫اســتالم املدعــى عليــه مــن املدعيــة عــدة مبالــغ لغــرض التجــارة ولــم‬\n‫يحــدد فيهــا نشــاط معــن األول مــؤرخ يف ‪ 1430/05/01‬ه ـ مببلــغ‬\n‫وقــدره خمســة عشــر ألــف ريــال الثانــي مــؤرخ يف ‪1430/05/21‬ه ـ مببلــغ‬\n‫وقــدره ســبعون ألــف ريــال والثالــث مــؤرخ يف ‪1430/07/10‬ه ـ مببلــغ‬\n‫وقــدره خمســة عشــر ألــف ريــال وبعــرض هــذه الســندات علــى املدعــى‬\n‫عليــه وكالــة قــال إن هــذه الســندات صحيحــة وصــادرة مــن موكلــي‬\n‫هكــذا أجــاب فجــرى إفهــام املدعيــة بــأن لهــا ميــن املدعــى عليــه أصالــة‬\n‫التــي هــذا نصهــا واهلل الــذي ال إلــه إال هــو وال رب ســواه لقــد اســتلمت‬\n‫مــن املدعيــة ‪ ........‬مبلغــا وقــدره مائــة ألــف ريــال مــن أجــل املتاجــرة بهــا‬\n‫وقــد أذنــت املدعيــة لــي إذنــا عامــا يف مجــال ونشــاط املتاجــرة ولــم حتــدد‬\n‫لــي نشــاطا معينــا ال يف بيــع وشــراء اخلضــروات والفواكــه وال يف مجــال‬\n‫االســتثمار يف ســيارة أجــرة وال غيرهــا وأنــي قــد وضعتهــا يف األســهم‬\n‫وخســرت فيهــا مبلغــا وقــدره اثنــان وعشــرون ألــف ريــال ولــم يتبــق مــن‬\n‫رأس املــال ســوى مبلــغ وقــدره ثمانيــة وســبعون ألــف ريــال وواهلل العظيــم‬\n‫إننــي لــم اســتلم مــن املدعيــة املبلــغ الــذي قــدره ثمانيــة آالف وثمامنائــة‬\n‫وثمانــون ريــاال ولــم أطلــب منهــا أو أفوضهــا يف ســداده عنــي ألي جهــة‬\n‫وال شــراء قيمــة هدايــا بــه وال غيرهــا واهلل العظيــم كمــا جــرى إفهــام‬\n\n\n                                                                                          ‫‪72‬‬\n\f     ‫املدعــى عليــه بــأن ملوكلــه ميــن املدعيــة التــي هــذا نصهــا واهلل الــذي‬\n     ‫ال إلــه إال هــو وال رب ســواه إننــي لــم أهــب مبلغــا وقــدره واحــدا وأربعــون‬\n     ‫ألــف ريــال للمدعــى عليــه ‪ ...‬الــذي يدعــي أنــه جــزء مــن املبلــغ املتبقــي‬\n     ‫مــن رأس مــال املضاربــة وال شــيئا منــه واهلل العظيــم فقالــت املدعيــة إننــي‬\n     ‫أريــد ميينــه هكــذا قــررت وقــال املدعــى عليــه وكالــة أطلــب إمهالــي‬\n     ‫للرجــوع ملوكلــي وســؤاله عــن ذلــك ويف جلســة أخــرى حضــر الطرفــان‬\n     ‫أصالــة واملعــرف باملدعيــة ‪ -‬وهــو ابنهــا ‪ ... -‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ ...‬وقــد صــادق املدعــى عليــه علــى إجابــة وكيلــه‬\n     ‫علــى الدعــوى يف اجللســة قبــل املاضيــة قائــا إن مــا ذكــره وكيلــي يف‬\n     ‫إجابتــه علــى الدعــوى يف اجللســة قبــل املاضيــة كلــه صحيــح وأقــر بــه‬\n     ‫هكــذا قــرر ثــم عرضــت علــى املدعــى عليــه أن يحلــف اليمــن التــي‬\n     ‫هــذا نصهــا واهلل الــذي ال إلــه إال هــو وال رب ســواه لقــد وصلنــي مــن‬\n     ‫املدعيــة ‪ .......‬مبلغــا وقــدره مائــة ألــف ريــال مــن أجــل املتاجــرة بهــا وقــد‬\n     ‫أذنــت املدعيــة لــي إذنــا عامــا يف مجــال ونشــاط املتاجــرة ولــم حتــدد لــي‬\n     ‫نشــاط معينــا ال يف بيــع وشــراء اخلضــروات والفواكــه وال يف مجــال‬\n     ‫االســتثمار يف ســيارة أجــرة وال غيرهــا وإنــي قــد وضعتهــا يف األســهم‬\n     ‫ولــم أضعهــا يف ســيارة أجــرة وال غيرهــا وقــد خســرت يف االســهم مبلغــا‬\n     ‫وقــدره اثنــان وعشــرون ألــف ريــال ولــم يبــق مــن رأس املــال ســوى مبلــغ‬\n     ‫وقــدره ثمانيــة وســبعون ألــف ريــال وواهلل العظيــم إننــي لــم أســتلم مــن‬\n     ‫املدعيــة املبلــغ الــذي قــدره ثمانيــة آالف وثمامنائــة وثمانــون ريــاال ولــم‬\n     ‫أطلــب منهــا أو أفوضهــا يف ســداده عنــي ألي جهــة وال شــراء قيمــة هدايــا‬\n     ‫بــه وال غيرهــا واهلل العظيــم وجــرى وعظــه وتخويفــه مــن عاقبــة اليمــن‬\n     ‫الكاذبــة فاســتعد ببذلهــا ثــم حلــف قائــا واهلل الــذي ال إلــه إال هــو وال‬\n\n\n‫‪73‬‬\n\f‫رب ســواه لقــد وصلنــي مــن املدعيــة ‪ ...‬مبلغــا وقــدره مائــة ألــف ريــال مــن‬\n‫أجــل املتاجــرة بهــا وقــد أذنــت املدعيــة لــي إذنــا عامــا يف مجــال ونشــاط‬\n‫املتاجــرة ولــم حتــدد لــي نشــاط معينــا ال يف بيــع وشــراء اخلضــروات‬\n‫والفواكــه وال يف مجــال االســتثمار يف ســيارة أجــرة وال غيرهــا وإنــي‬\n‫قــد وضعتهــا يف األســهم ولــم أضعهــا يف ســيارة أجــرة وال غيرهــا وقــد‬\n‫خســرت يف االســهم مبلغــا وقــدره اثنــان وعشــرون ألــف ريــال ولــم يبــق مــن‬\n‫رأس املــال ســوى مبلــغ وقــدره ثمانيــة وســبعون ألــف ريــال وواهلل العظيــم‬\n‫إننــي لــم أســتلم مــن املدعيــة املبلــغ الــذي قــدره ثمانيــة آالف وثمامنائــة‬\n‫وثمانــون ريــاال ولــم أطلــب منهــا أو أفوضهــا يف ســداده عنــي ألي جهــة‬\n‫وال شــراء قيمــة هدايــا بــه وال غيرهــا واهلل العظيــم هكــذا حلــف ثــم‬\n          ‫عرضــت علــى املدعيــة أن حتلــف اليمــن التــي هــذا نصها‪...‬يتبــع‬\n‫واهلل الــذي ال إلــه إال هــو وال رب ســواه إننــي لــم أهــب مبلغــا وقــدره واحــد‬\n‫وأربعــون ألــف ريــال للمدعــى عليــه ‪ ...‬الــذي يدعــي أنــه جــزء مــن املبلــغ‬\n‫املتبقــي مــن مــال املضاربــة وال شــيئا منــه واهلل العظيــم وجــرى وعظهــا‬\n‫وتخويفهــا مــن عاقبــة اليمــن الكاذبــة فاســتعدت ببذلهــا ثــم حلفــت‬\n‫قائلــة واهلل الــذي ال إلــه إال هــو وال رب ســواه إننــي لــم أهــب مبلغــا وقــدره‬\n‫واحــد وأربعــون ألــف ريــال للمدعــى عليــه ‪ ...‬الــذي يدعــي أنــه جــزء مــن‬\n‫املبلــغ املتبقــي مــن مــال املضاربــة وال شــيئا منــه واهلل العظيــم هكــذا‬\n‫حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه‬\n‫باســتالمه مــن املدعيــة مبلغــا وقــدره مائــة ألــف ريــال لغــرض التجــارة‬\n‫ودفعــه باخلســارة فيــه وإقــراره ببقــاء مبلــغ وقــدره ثمانيــة وســبعون ألــف‬\n‫ريــال مــن رأس املــال بعــد اخلســارة وإقــراره ببقــاء مبلــغ وقــدره ســبعة‬\n‫وثالثــون ألــف ريــال منــه يف ذمتــه ونظــرا لعــدم وجــود بينــة لــدى املدعيــة‬\n\n\n                                                                                         ‫‪74‬‬\n\f     ‫تثبــت اشــتراطها علــى املدعــى عليــه املتاجــرة يف املبلــغ املذكــور يف‬\n     ‫نشــاط اخلضــروات والفواكــه أو ســيارة أجــرة ولعــدم وجــود بينــة لــدى‬\n     ‫املدعيــة أيضــا تثبــت أن املدعــى عليــه قــد فوضهــا أو طلــب منهــا دفــع‬\n     ‫مبلــغ الثمانيــة آالف وثمامنائــة وثمانــن ريــاال ونظــرا لعــدم وجــود بينــة‬\n     ‫لــدى املدعــى عليــه تثبــت صحــة دفعــه مــن أن املدعيــة قــد وهبــت لــه‬\n     ‫املبلــغ املتبقــي بعــد املضاربــة وقــدره واحــد وأربعــون ألــف ريــال وبنــاء علــى‬\n     ‫األميــان التــي حلفهــا الطرفــان وألن ممــا يقــوي دفــع املدعــى عليــه بعــدم‬\n     ‫اشــتراط املدعيــة عليــه نشــاطا معينــا يف املضاربــة مــا جــاء يف ســندات‬\n     ‫القبــض الثالثــة التــي أبرزتهــا املدعيــة التــي تضمنــت اســتالم املدعــى‬\n     ‫عليــه املبالــغ لغــرض التجــارة دون حتديــد نشــاط أو شــروط معينــة وملــا‬\n     ‫رواه البيهقــي عــن ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى‬\n     ‫اهلل عليــه وســلم قــال ( لــو يعطــى النــاس بدعواهــم الدعــى رجــال أمــوال‬\n     ‫قــوم ودماءهــم لكــن البينــة علــى املدعــي واليمــن علــى مــن أنكــر) وملــا‬\n     ‫تقــرر شــرعا يف أن املضــارب أمــن والقــول قولــه فيمــا يدعيــه مــن ربــح‬\n     ‫أو خســارة أو أن يكــون رب املــال قــد أذن لــه يف املضاربــة إذنــا معينــا‬\n     ‫بشــروط أو بدونهــا قــال يف كشــاف القنــاع ‪ ( 524/8‬والعامــل أمــن يف‬\n     ‫مــال املضاربــة) ثــم قــال ( والقــول قولــه يف قــدر رأس املــال والربــح وأنــه‬\n     ‫ربــح أو لــم يربــح وفيمــا يدعيــه مــن هــاك أو خســران) وقــال يف كشــاف‬\n     ‫القنــاع أيضــا ‪ ( 457/8‬أو اختلفــا أي الوكيــل واملضــارب مع رب املال يف‬\n     ‫صفــة اإلذن يف الوكالــة أو املضاربــة فقولهمــا أي الوكيــل واملضــارب‬\n     ‫بيمينهمــا ألنهمــا أمينــان يف التصــرف فقبــل قولهمــا ) لــذا كلــه فقــد‬\n     ‫ألزمــت املدعــى عليــه ‪ ...........‬بــأن يدفــع للمدعيــة ‪ ...‬مبلغــا وقــدره ثمانيــة‬\n     ‫وســبعون ألــف ريــال وصرفــت النظــر عــن بقيــة مــا تطالــب بــه املدعيــة‬\n\n\n‫‪75‬‬\n\f‫وأخليــت ســبيل املدعــى عليــه منــه وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــررا عــدم القناعــة وطلبــا التمييــز فأجيبــا لطلبهمــا‬\n‫وجــرى إفهامهمــا بتعليمــات االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/03‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n‫يــوم اإلثنــن املوافــق ‪ 1434/06/26‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34233074‬يف‬\n‫‪1434/06/06‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم ) قاضــي اســتئناف‬\n‫د‪ ....‬ختــم وتوقيــع قاضــي اســتئناف ‪ ...‬ختــم وتوقيــع قاضــي اســتئناف‬\n‫‪ ...‬ختــم وتوقيــع ‪،‬وحتــى ال يخفــى امــرت بإثباتــه علــى ضبطــه وســجله‬\n‫‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/06/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ويف يــوم االحد‬\n‫املوافــق ‪1434/09/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 15‬وفيهــا‬\n‫حضــرت املدعيــة ‪ ...‬وقــررت بقولهــا لقد اســتلمت كامل املبلغ احملكوم‬\n‫لــي بباطــن الصــك الصــادر برقــم ‪ 3458957‬يف ‪1434/03/09‬ه ـ وقــدره‬\n‫ثمانيــة وســبعون ألــف ريــال هكــذا قــررت وحتــى ال يخفــى أمــرت‬\n‫بإثباتــه علــى ضبطــه وســجله وختمــت اجللســة الســاعة ‪ ، 01 : 20‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1434/09/20‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n\n\n                                                                                  ‫‪76‬‬\n\f     ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن‬\n     ‫فضيلــة الشــيخ‪ .../‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n     ‫‪3458957‬وتاريــخ ‪1434/3/9‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬واحملكــوم‬\n     ‫فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم‪ .‬وصلــى اهلل علــى نبينــا‬\n                                          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":68,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c560185bb4e6de8fdaf5e540ce398ae1b940faf7baa444c1789f659d505b2514","normalized_text_hash":"bee682684036c7677b43536e77e5a6a0a58d7f19cdbfcb26c2a57094b0f34ab0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p68-3458957"},{"id":"c01c9f74-4f02-5568-8fc7-81b0e1a63d6d","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -مضاربة -دعوى على مصرف بطلب إثبات شراكة -اختصاص جلنة املنازعات املصرفية بنظر القضايا املصرفية - مشاركة جتارية -طلب إثبات عقد لشراكة على الصفة املوضحة يف الدعوى -طلب إثبات خسارة رأس املال -عقد تسهيالت بنكية -صرف النظر عن الدعوى لعدم االختصاص الوالئي.","document_number":"3462403","case_number":"32234537","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"شراكة -مضاربة -دعوى على مصرف بطلب إثبات شراكة -اختصاص جلنة املنازعات املصرفية بنظر القضايا املصرفية - مشاركة جتارية -طلب إثبات عقد لشراكة على الصفة املوضحة يف الدعوى -طلب إثبات خسارة رأس املال -عقد تسهيالت بنكية -صرف النظر عن الدعوى لعدم االختصاص الوالئي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/3/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3462403 :‬‬\n                   ‫َر ْق ُم الدعوى‪32234537 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34204683‬تاريخه‪1434/5/4:‬هـ‬\n\n\n‫شــراكة ‪ -‬مضاربــة ‪ -‬دعــوى علــى مصــرف بطلــب إثبــات شــراكة‬\n‫‪ -‬اختصــاص جلنــة املنازعــات املصرفيــة بنظــر القضايــا املصرفيــة ‪-‬‬\n‫مشــاركة جتاريــة ‪ -‬طلــب إثبــات عقــد لشــراكة علــى الصفــة املوضحــة‬\n‫يف الدعــوى ‪ -‬طلــب إثبــات خســارة رأس املــال ‪ -‬عقــد تســهيالت بنكيــة‬\n           ‫‪ -‬صــرف النظــر عــن الدعــوى لعــدم االختصــاص الوالئــي‪.‬‬\n\n\n\n\n‫األمــر الســامي الكــرمي رقــم ‪ 37441‬يف ‪1433/8/11‬ه ـ املعمم من قبل وزير‬\n‫العــدل برقــم ‪/13‬ت‪ 4708/‬وتاريــخ ‪1433/9/19‬ه ـ املتضمــن اختصــاص‬\n‫جلنــة املنازعــات املصرفيــة بالنظــر يف القضايــا املصرفيــة األصليــة ‪-‬‬\n                             ‫والنظــر يف القضايــا املصرفيــة بالتبعيــة ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل صاحــب مؤسســة جتاريــة ضــد وكيــل مصــرف جتــاري‬\n‫بــأن موكلــه أبــرم اتفاقيــة شــراكة مــع املدعــى عليهــا مبوجــب‬\n‫هــذه االتفاقيــة قامــت املدعــى عليهــا مبنــح موكلــه مبلغــا قــدره‬\n‫(‪)13.801.667‬ريــال بعــد توقيــع موكلــه علــى ســند ألمــر بكامــل‬\n‫املبلــغ وذلــك بهــدف تشــغيل هــذا املبلــغ يف املجــال التجــاري الــذي يحســنه‬\n‫وهــو جتــارة األجهــزة واملعــدات واملســتلزمات الطبيــة مقابــل ربــح قــدره‬\n\n                                                                                     ‫‪78‬‬\n\f     ‫(‪ )%7.5‬بالشــروط والبنــود التــي مت تفصيلهــا يف االتفاقيــة ‪ ،‬بعــد مــرور‬\n     ‫ثمانيــة أشــهر قــام مــوكل املدعــي مبنــح املدعــى عليهــا (‪)2.000.000‬‬\n     ‫ريــال الــى أن يتــم اجــراء احملاســبة بينهمــا ‪ .‬أفــاد املدعــى وكالــة بــأن‬\n     ‫موكلــه منيــت جتارتــه بخســارة فادحــة أدت الــى هــاك رأس املــال‬\n     ‫وتوقيــع غرامــات ماليــة باهظــة ملصلحــة اجلمــارك وذلــك بســبب تقلبــات‬\n                                      ‫األســعار ومنــع دخــول البضاعــة للمملكــة ‪.‬‬\n     ‫‪ ،‬ذكــر املدعــى وكالــة بــان موكلــه نقــل ذلــك للمدعى عليهــا فأصرت‬\n     ‫علــى أن يعيــد املدعــى رأس مالهــا دون خصــم وأنهــا لــن تتحمــل أي‬\n     ‫خســارة ماليــة منــى بهــا املدعــى ‪ ،‬طلــب املدعــى وكالــة اثبــات شــراكة‬\n     ‫املدعــى عليهــا ملوكلــه وفــق مــا مت تفصيلــه ومــا يلــزم تبعــا لذلــك مــن‬\n     ‫إثبــات خســارة موكلــه لــرأس املــال ‪ ،‬اإليعــاز ملــن يلــزم بإيقــاف النظــر يف‬\n     ‫الدعــوى املرفوعــة مــن املدعــى عليهــا ضــد موكلــه املنظــورة لــدى جلنــة‬\n     ‫تســوية املنازعــات املصرفيــة حيــث ان تاريــخ قيــد هــذه املعاملــة أســبق مــن‬\n     ‫املعاملــة املقيــدة لــدي اللجنــة املذكــورة ‪ ،‬أجــاب املدعــى عليــه وكالــة‬\n     ‫بصفتــه وكيــا عــن املصــرف بــأن العقــد الــذي بــن موكلــه واملدعــى‬\n     ‫أصالــة عقــد تســهيالت بنكيــة وأن عقــود التســهيالت بــكل أنواعهــا‬\n     ‫تعــد مــن األعمــال املصرفيــة املختــص بنظرهــا جلنــة تســوية املنازعــات‬\n     ‫املصرفيــة ‪ ،‬طلــب املدعــى عليــه وكالــة رد الدعــوى لعــدم االختصــاص‬\n     ‫الوالئــي ‪ ،‬أجــاب املدعــى وكالــة بــأن االختصــاص منعقــد للمحكمــة‬\n     ‫العامــة وليــس للجنــة املذكــورة ألن العقــد أبــرم بــن موكلــه وشــركة‬\n     ‫‪ ......‬وليــس بنــك ‪ ،‬بتأمــل مــا ســبق وبنــاء علــى األمــر الســامي الكــرمي‬\n     ‫رقــم ‪ 37441‬يف ‪1433/8/11‬ه ـ والــذي نــص علــى تســمية جلنة املنازعات‬\n     ‫املصرفيــة وأنــاط بهــا النظــر يف القضايــا املصرفيــة األصليــة والنظــر يف‬\n\n\n‫‪79‬‬\n\f‫القضايــا املصرفيــة بالتبعيــة وألن هــذه الدعــوى بــن مؤسســة جتاريــة‬\n‫ومصــرف بخصــوص تســهيالت بنكيــة لــذا صــدر احلكــم بصــرف‬\n‫النظــر عــن دعــوى املدعــى لعــدم االختصــاص الوالئــي ‪ ،‬اعتــرض املدعى‬\n                 ‫وكالــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامة بالرياض برقم ‪ 32234537‬املقيدة باحملكمة برقم ‪32731815‬‬\n‫وتاريــخ ‪1433/2/29‬ه ـ ففــي يــوم االثنــن ‪ 1433/2/29‬ه ـ أفتتحــت‬\n‫اجللســة االولــى الســاعة ‪ - 10 : 28‬وفيهــا حضــر ‪...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬الريــاض بصفتــه وكيــا عــن ‪...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬أصالــة عــن نفســه وبصفتــه صاحــب مؤسســة‬\n‫‪...‬للتجــارة مبوجــب الوكالــة رقــم ‪ 51655‬وتاريــخ ‪ 1432/6/8‬ه ـ جلــد‬\n‫‪ 10708‬الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــده وقــد‬\n‫تضمنــت الوكالــة أن للوكيــل حــق املرافعــة واملدافعــة واالقــرار وحضــر‬\n‫املدعــى عليــه وكالــه ‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬الريــاض‬\n‫فادعــى االول قائــا انــه بتاريــخ ‪1430/3/25‬ه ـ املوافــق‪2009/3/22‬م‬\n‫مت إبــرام اتفاقيــة شــراكة بــن موكلــي واملدعــى عليهــا مبوجبهــا قامــت‬\n‫املدعــى عليهــا مبنــح موكلــي مبلغـ ًا وقــدره ( ‪13.801.667‬ريــال )ثالثــة‬\n‫عشــر مليــون وثمامنائــة وواحــد ألــف وســتمائة وســبعة وســتون ريــا ًال بعــد‬\n‫توقيعــه علــى ســند ألمــر بكامــل هــذه القيمــة وذلــك بهــدف تشــغيل هــذا‬\n‫املبلــغ يف املجــال التجــاري الــذي يحســنه وهــو جتــارة األجهــزة واملعــدات‬\n\n                                                                                    ‫‪80‬‬\n\f     ‫واملســتلزمات الطبيــة مقابــل ربــح قــدره( ‪ ) %7.5‬وذلك بالشــروط والبنود‬\n     ‫التــي مت تفصيلهــا باالتفاقيــة املبرمــة بينهمــا واملرفقــة طيــه( مرفــق‬\n     ‫مســتند رقــم‪ -11/1‬صــورة مــن االتفاقيــة‪ +‬صــورة مــن الســند ) وقــد‬\n     ‫قــام موكلــي بتشــغيل هــذا املبلــغ يف املجــال أعــاه وبعــد مــرور ثمانيــة‬\n     ‫أشــهر تقريبـ ًا مــن تاريــخ التعاقــد قــام موكلــي مبنــح املدعــى عليهــا مبلــغ‬\n     ‫وقــدره ( ‪ 2.000.000‬ريــال ) مليونــي ريــال إلــى أن يتــم إجــراء احملاســبة‬\n     ‫بينهمــا اال أن موكلــي بعــد ذلــك قــد ُمنيــت جتارتــه بخســارة فادحــة أدت‬\n     ‫إلــى هــاك رأس املــال وذلــك نتيجــة لتقلبــات أســعار البضاعــة محــل‬\n     ‫الدعــوى وعــدم ثباتهــا يف الســوق التجاريــة الداخليــة و اخلارجيــة ونتيجــة‬\n     ‫لصــدور مراســيم ســامية حتظــر ومتنــع دخــول مثــل هــذه البضاعــة أرض‬\n     ‫اململكــة يف الوقــت الــذي كان موكلــي قــد عقــد فيــه العديــد والعديــد‬\n     ‫مــن الصفقــات واالتفاقيــات بهــذا اخلصــوص هنالــك وعليــه فقــد متــت‬\n     ‫مصــادرة هــذه البضائــع مــن قبــل مصلحــة اجلمــارك وتوقيــع غرامــات‬\n     ‫ماليــة باهظــة علــى موكلــي وعلــى إثــر ذلــك قــام موكلــي بنقــل كامــل‬\n     ‫هــذه الوقائــع للمدعــى عليهــا لكــن دون فائــدة تذكــر حيــث أصــرت‬\n     ‫املدعــى عليهــا علــى موكلــي أن يعيــد لهــا رأس مالهــا ودون خصــم مــا‬\n     ‫قــام موكلــي بســداده لهــا وفــق مــا ذكــر أعــاه وأنهــا لــن تتحمــل مغبــة‬\n     ‫أي خســارة ماليــة قــد ُم ِنـ َـي بهــا موكلــي ليصبــح موكلــي مطالــب بــأن‬\n     ‫يســدد للمدعــى عليهــا مبلــغ وقــدره( ‪ 13.767.823.58‬ريــال ) ثالثــة‬\n     ‫عشــر مليــون وســبعمائة وســبعة وســتني الــف وثمامنائــة وثالثــة وعشــرون‬\n     ‫ريــا ًال وثمانيــة وخمســون هللــة بــد ًال عــن مبلــغ وقــدره( ‪11.767.823.58‬‬\n     ‫ريــال ) أحــد عشــر مليــون وســبعمائة وســبعة وســتني ألــف وثمامنائة وثالثة‬\n     ‫وعشــرون ريــا ًال وثمانيــة وخمســون هللــة ولــم تقــف املدعــى عليهــا عنــد‬\n\n\n‫‪81‬‬\n\f‫حــد رفضهــا لتحمــل هــاك رأس املــال ملــا تقــدم بيانــه بــل قامــت برفــع‬\n‫دعــوى ضــد موكلــي لــدى جلنــة تســوية املنازعــات املصرفيــة تطالبــه‬\n‫فيهــا ب ــسداد مبلــغ وقـ ـ ــدره (‪ 13.767.823.58‬ريال)ثالثــة عشــر مليــون‬\n‫وســبعمائة وســبعة وســتني ألــف وثمامنائــة وثالثــة وعشــرين ريــا ًال وثمانيــة‬\n‫وخمســن هللــة (مرفــق مســتند رقــم‪ -3/2-‬صــورة مــن الئحــة الدعــوى )‬\n‫نطلــب مــن فضيلتكــم مــا يلي‪-:‬إثبــات شــراكة املدعــى عليهــا ملوكلــي‬\n‫وفــق مــا مت تفصيلــه أعــاه ومــا يلــزم تبع ـ ًا لذلــك مــن إثبــات خســارة‬\n‫موكلــي لــرأس املــال موضــوع الدعــوى مــن عدمــه واإليعــاز ملــن يلــزم‬\n‫بإيقــاف النظــر يف دعــوى املدعــى عليهــا لــدى جلنــة تســوية املنازعــات‬\n‫املصرفيــة حلــن إنهــاء النــزاع لــدى فضيلتكــم ســيما وأن دعوانــا ضــد‬\n‫املدعــى عليهــا أســبق مــن دعواهــا علينــا إذ أن دعوانــا لــدى فضيلتكــم‬\n‫مت قيدهــا برقــم (‪ ) 32/731815‬يف ‪1432/6/18‬ه ـ بينمــا دعــوى‬\n‫املدعــى عليهــا مت قيدهــا لــدى جلنــة تســوية املنازعــات املصرفيــة يف‬\n‫‪1432/10/7‬ه ـ وذلــك حرصـ ًا علــى عــدم تضــارب األحــكام القضائيــة‬\n‫يف املوضــوع هــذه دعــواي ونظــرا لعــدم احضــار املدعــى عليــه ألصــل‬\n                                              ‫الوكالــة فقــد قــررت رفــع اجللســة‬\n‫ثــم يف يــوم الثالثــاء املوافــق‪ 1433/06/24‬ه ـ افتتحــت اجللســة الثانيــة‬\n‫الســاعة ‪ 10 : 48‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n‫وأبــرز املدعــى عليــه وكالــة وكالتــه فوجدتهــا متضمنــة توكيــل ‪...‬‬\n‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪...‬بصفتــه وكيــا عــن ‪...‬و‪...‬‬\n‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬بصفتهــم مــن أعضــاء مجلــس إدارة شــركة ‪.....‬‬\n‫حســب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف بــوزارة التجــارة‬\n‫والصناعــة برقــم ‪ 7191‬وتاريــخ ‪1432/12/24‬ه ـ واملخــول لــه فيهــا‬\n\n\n                                                                                      ‫‪82‬‬\n\f     ‫حــق التمثيــل أمــام جميــع جهــات التقاضــي وإقامــة الدعــوى واملرافعــة‬\n     ‫واملدافعــة وبعــرض الدعــوى علــى املدعــى عليــه وكالــة أجــاب أقــام‬\n     ‫ـاء علــى عقــد التســهيالت املبــرم بينــه وبــن موكلتــي‬  ‫املدعــي دعــواه بنـ ً‬\n     ‫والــذي يتضمــن خــط عقــود مشــاركة وخــط عقود بيع آجــل ‪ ،‬وحيث إن‬\n     ‫عقــود التســهيالت بــكل أنوعهــا تعــد مــن األعمــال املصرفيــة التــي تقــوم‬\n     ‫بهــا البنــوك‪ ،‬و التــي يكــون النظــر يف الدعــاوى املتعلقــة بهــا منعقــد ًا‬\n     ‫للجنــة تســوية املنازعــات املصرفيــة ‪ ،‬وذلــك اســتناد ًا لألمــر الســامي‬\n     ‫رقــم ‪ 8/729‬وتاريــخ ‪1407/7/10‬ه ـ يف الفقــرة األولــى منــه والــذي جــاء‬\n     ‫فيــه منــع احملاكــم مــن ســماع الدعــاوى التــي تقــدم ضــد البنــوك إال‬\n     ‫بعــد أخــذ املوافقــة علــى ذلــك مــن املقــام الســامي كمــا جــاء يف الفقــرة‬\n     ‫الثانيــة منــه بتشــكيل جلنــة يف مؤسســة النقــد مــن ثالثــة أشــخاص مــن‬\n     ‫ذوي التخصــص لدراســة القضايــا بــن البنــوك وعمالئهــا واســتناد ًا علــى‬\n     ‫األمــر الســامي رقــم ‪ 110/4‬وتاريخ‪1409/1/2‬ه ـ والــذي جــاء التنبيــه‬\n     ‫فيــه علــى أن املقصــود بالدعــاوى الــواردة يف الفقرتــن األولــى والثانيــة‬\n     ‫مــن األمــر الســامي الســابق رقــم(‪ )8/729‬هــي الدعــاوى ذات الصفــة‬\n     ‫املصرفيــة التــي تنشــأ مــن ممارســة البنــك ألعمالــه املصرفيــة البحتــة‬\n     ‫مثــل فتــح االعتمــادات واحلســابات بأنواعهــا والقــروض ونحوهــا مــن‬\n     ‫األعمــال املصرفيــة وحيــث اســتقر عمــل احملاكــم العامــة علــى صــرف‬\n     ‫النظــر عــن مثــل هــذه الدعــاوى لعــدم االختصــاص ونرفــق لكــم قــرار‬\n     ‫مؤيــد مــن االســتئناف صــادر مــن احملكمــة العامــة بالريــاض ينــص علــى‬\n     ‫صــرف النظــر عــن النــزاع لعــدم االختصــاص وحيــث أنــه توجــد اآلن‬\n     ‫دعــوى قائمــة لــدى جلنــة تســوية املنازعــات املصرفيــة تخــص نفــس محــل‬\n     ‫النــزاع مقيــدة لــدى جلنــة تســوية املنازعــات املصرفيــة برقــم ‪1432/379‬‬\n\n\n‫‪83‬‬\n\f‫ـاء علــى مــا ُذكــر أعــاه وعلــى املــادة الثانيــة والســبعني مــن نظــام‬  ‫وبنـ ُ‬\n‫املرافعــات الشــرعية املتعلقــة بالدفــع بعــدم اختصــاص احملكمــة النوعي‬\n‫والتــي نصــت علــى أنــه ‪...« :‬يجــوز الدفــع بــه يف أي مرحلــة تكــون فيهــا‬\n‫الدعــوى وتأسيسـ ًا علــى مــا تقــدم نطلــب مــن فضيلتكــم صــرف النظــر‬\n‫عــن دعــوى املدعــي لعــدم اختصــاص احملكمــة بالنظــر فيهــا هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي وكالــة أجــاب أطلــب مهلــة للــرد علــى‬\n        ‫مــا دفــع بــه املدعــى عليــه وكالــة هكــذا أجــاب ورفعــت اجللســة‬\n‫ثــم يف يــوم الثالثــاء املوافــق‪ 1433/11/02‬ه ـ افتتحــت اجللســة الثالثــة‬\n‫الســاعة ‪ 11 : 30‬وفيهــا حضــر طــريف الدعــوى وقــدم وكيــل املدعــي‬\n‫مذكــرة جوابيــة هــذا نصهــا الســام عليكــم ورحمــة اهلل وبركاتــه‬\n‫وبع ــد ‪ -‬فباإلشــارة إلــى مذكــرة املدعــى عليهــا رقــم( ‪ )1987‬واملؤرخــة‬\n‫يف ‪1433/6/22‬ه ـ واملقدمــة لــدى فضيلتكــم رد ًا علــى دعوانــا املقيــدة‬\n‫لــدى فضيلتكــم برقــم(‪ )32/731815‬وتاريــخ ‪1432/6/18‬ه ـ والتــي‬\n‫طلــب فيهــا وكيــل املدعــى عليهــا مــن فضيلتكــم صــرف النظــر‬\n‫عنهــا لعــدم اختصــاص احملكمــة العامــة بنظرهــا ففيمــا يلــي نــورد‬\n‫لفضيلتكــم ردنــا علــى انعقــاد اختصــاص نظــر دعوانــا هــذه للمحكمــة‬\n                                     ‫العامــة وذلــك علــى النحــو اآلتــي بيانــه‪-:‬‬\n‫‪ -1-‬فمــن خــال وقائــع دعوانــا ومــا مت تقدميــه فيهــا مــن املســتندات‬\n‫مــن قِ بــل طــريف الدعــوى يتضــح جلي ـ ًا لــدى فضيلتكــم أننــا نهــدف مــن‬\n‫دعوانــا اســتصدار حكــم يقضــي بإثبــات شــراكة موكلــي للمدعــى‬\n‫عليهــا شــركة ‪ .....‬وهــي شــركة مســاهمة ذات الســجل التجــاري رقــم‬\n‫(‪ )........‬بنــاء علــى عقــود الشــراكة املبرمــة بينهمــا واملقــرة مــن جانبهمــا‬\n‫مبســماها ( عقــود مشــاركة ) وكمــا ال يخفــى علــى فضيلتكــم‬\n\n\n                                                                                        ‫‪84‬‬\n\f     ‫علمــه أن مثــل هــذا النــوع مــن الدعــاوى تختــص احملكمــة العامــة بنظــره‬\n                                                                            ‫وصف ـ ًا وقيــداً‪.‬‬\n     ‫‪ -2-‬اســتناد وكيــل املدعــى عليهــا علــى األمــر الســامي رقــم ‪8/729‬‬\n     ‫وتاريــخ ‪1407/7/10‬ه ـ ومــا يســتفاد منــه مــن منــع احملاكــم مــن ســماع‬\n     ‫الدعــاوى التــي تقــام ضــد البنــوك إال بعــد أخــذ موافقــة املقــام الســامي‬\n     ‫علــى ذلــك هــو يف حقيقــة األمــر وواقعــه محــل نظــر وموضــع تأمــل ذلــك‬\n     ‫لتضمــن األمــر الســامي نفســه مــا نصــه» وحيــث الحظنــا أن بعضــا مــن‬\n     ‫القضايــا التــي رفعــت إلحالتهــا إلــى هــذه اللجنــة قضايــا مدنيــة نتجت عن‬\n     ‫ممارســة البنــك لنشــاطه كشــخص معنــوي وليســت قضايــا مصرفيــة‬\n     ‫حصلــت إثــر ممارســة البنــك لنشــاطه املصــريف ‪ « ...‬وهــذا يعنــي أن البنك‬\n     ‫إن مــارس عملــه كعمــل مصــريف بحــت فمــا نتــج عــن ذلــك مــن منازعــات‬\n     ‫فينعقــد االختصــاص بنظرهــا للجنــة تســوية املنازعــات املصرفيــة أمــا إن‬\n     ‫مــارس البنــك عملــه كشــخص معنــوي يدخــل يف عمليــات بيــع الســلع أو‬\n     ‫شــرائها وإلــى مــا شــابه ذلــك مــن أعمــال وتصرفــات وعقــود كمــا هــو‬\n     ‫موضــوع دعوانــا ثــم ينشــأ عــن ذلــك منازعــات وقضايــا فإنــه حينئــذٍ وبــا‬\n     ‫أدنــى شــك اســتناد ًا ملنطــوق األمــر الســامي نفســه ومــا ورد بيانــه فيــه مــن‬\n     ‫قضيــة البنــك‪ .....‬ضــد ‪ ......‬علــى إثــر نــزاع علــى أرض فــإن االختصــاص‬\n     ‫ينعقــد لغيــر جلنــة املنازعــات املصرفيــة ســواء أكانــت جهــة االختصــاص‬\n     ‫احملكمــة العامــة أو للدوائـ ــر التجاريــة يف ديــوان املظالــم؛ ه ــذا كلــه‬\n     ‫إن ســلمنا أن خصمنــا يف ه ــذه الدعـ ــوى بنــك ‪ .....‬وليــس شــركة ‪.....‬‬\n                                ‫لالســتثمار ذات الســجل التجــاري املرصــود أعــاه‬\n     ‫‪ -3-‬وممــا يعــزز مــا ســبقت اإلشــارة إليــه أعــاه مــن أن خصمنــا يف هــذه‬\n     ‫الدعــوى شــركة ‪ ....‬وليــس بنــك ‪ ....‬هــو أن البنــوك يحظــر عليها اســتناد ًا‬\n\n\n‫‪85‬‬\n\f‫لنصــوص املــواد (‪8‬؛‪9‬؛‪ )10‬مــن نظــام مراقبــة البنــوك الصــادر باملرســوم‬\n‫امللكــي رقــم م‪ 5/‬وتاريــخ ‪1386/2/22‬ه ـ أن يعطــي قرضـ ًا أو أن يقــدم‬\n‫تســهيالت ائتمانيــة أو أن يشــتغل حلســابه أو بالعمولــة بتجــارة اجلملــة‬\n‫أو التجزئــة مبــا يف ذلــك جتــارة االســتيراد أو التصديــر أو أن تكــون‬\n‫لــه مصلحــة مباشــرة كمســاهم أو كشــريك يف أي مشــروع جتــاري‬\n‫أو صناعــي أو زراعــي أو أي مشــروع آخــر وهــذا بتمامــه مــا قامــت بــه‬\n‫املدعــى عليهــا جتــاه موكلــي ثـ ّـم هــي اآلن تســعى يف نقــض مــا مت جهتهــا‬\n‫فالشــك أن ســعيها واحلــال هــذه يجــب رده عليهــا إذ القاعــدة الفقهيــة‬\n‫تنطــق يف هــذا املقــام أن « مــن ســعى يف نقــض مــا مت مــن جهتــه فســعيه‬\n                                                                  ‫مــردود عليــه «‬\n‫‪ -4-‬بشــأن الســابقة القضائيــة التــي أوردهــا وكيــل املدعــى عليهــا يف‬\n‫املذكــرة محــل الــرد ليدلــل بهــا علــى عــدم اختصــاص احملاكــم العامــة‬\n‫بنظــر هــذا النــوع مــن القضايــا ؛ فــإن ردنــا علــى ذلــك يتلخــص يف أن‬\n‫الوقائــع واملطالــب الــوارد ذكرهــا يف احلكــم املرفــق تختلــف متام ـ ًا‬\n‫عــن وقائــع دعوانــا ومســتنداتها ومطالبنــا فيهــا ذلــك أن احلكــم املرفــق‬\n‫يتضمــن قيــام البنــك بتصرفــات وأعمــال جتــاه عميلــه تتعلــق بأســهم‬\n‫ا مصرفي ـ ًا‬   ‫وحســابات ورهــن محفظــات إلــى آخــره ممــا يعتبــر عم ـ ً‬\n‫بحتـ ًا إضافــة إلــى أن املدعــي يف دعــواه املبينــة يف احلكــم املرفــق يهــدف‬\n‫إلــى احلكــم علــى البنــك بتعويضــات وخســائر ومــا إلــى ذلــك وال يخفــى‬\n‫أن دعوانــا كمــا تقــدم ذكــره أعــاه نهــدف مــن ورائهــا إلــى احلكــم‬\n‫بإثبــات الشــراكة بيننــا وبــن املدعــى عليهــا بنــاء علــى عقــد الشــراكة‬\n‫املبــرم بيننــا واملقــر بــه مــن قِ بــل طــريف العقــد فالقيــاس مــع الفــارق ‪-5‬‬\n‫فيمــا يتعلــق بوجــود دعــوى مقامــة مــن املدعــى عليهــا ضــد موكلتــي‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫لــدى جلنــة تســوية املنازعــات املصرفيــة واملقيــدة برقــم (‪)1432/379‬‬\n     ‫وتاريــخ ‪1432/10/7‬ه ـ واعتبــار ذلــك مــن موجبــات ومؤيــدات احلكــم‬\n     ‫بصــرف النظــر عــن دعوانــا ؛ فجوابنــا علــى ذلــك يتمثــل يف أن وجــود‬\n     ‫دعــوى منظــورة لــدى أي جهتــن قضائيتــن يف آن واحــد ال يســتوجب‬\n     ‫صــرف نظــر أحداهمــا مــن غيــر تريــث وتأمــل بــل قــد تكــون اجلهتــان‬\n     ‫معنيتــان بالفصــل يف موضــوع النــزاع أو غيــر معنيتــن يف آن واحــد وذلــك‬\n     ‫مــا يعــرف بتدافــع االختصــاص ســلب ًا أو إيجاب ـ ًا ؛ كمــا وإن كان مــن‬\n     ‫املفتــرض علــى حــد فهــم وكيــل املدعــى عليهــا أن وجــود الدعــوى لــدى‬\n     ‫جلنــة تســوية املنازعــات يقتضــي احلكــم بصــرف النظــر عــن نزاعنــا لــدى‬\n     ‫فضيلتكــم فــإن دعــوى املدعــى عليهــا هــي مــن ينبغــي صــرف النظــر‬\n     ‫عنهــا لــدى جلنــة التســوية وذلــك كــون دعوانــا لــدى احملكمــة العامــة‬\n     ‫هــي األســبق مــن دعــوى املدعــى عليهــا لــدى اللجنــة املصرفيــة ؛ وهــذا‬\n     ‫ثابــت مــن خــال مســتندات التبليــغ باحلضــور والتــي يتضــح منهــا أن‬\n     ‫تاريــخ تقدمنــا بالدعــوى لــدى احملكمــة العامــة يف ‪1432/6/18‬ه ـ‬\n     ‫بينمــا تاريــخ تقــدم املدعــى عليهــا بدعواهــا لــدى جلنــة تســوية املنازعــات‬\n     ‫املصرفيــة وقــع يف تاريــخ ‪1432/10/7‬ه ـ أي بعــد علمهــا بتقدمنا بدعوى‬\n     ‫ـاء علــى مــا تقــدم ‪ -:‬نطلــب مــن فضيلتكــم مــا‬   ‫احملكمــة العامــة وبنـ ً‬\n     ‫يلــي‪ -1-:‬إصــدار حكــم إثبــات شــراكة املدعــى عليهــا ملوكلــي بنــاء‬\n            ‫علــى عقــد الشــراكة املبــرم بينهمــا ووفــق مــا مت تفصيلــه أعــاه‪.‬‬\n     ‫‪ -2‬اإليعــاز ملــن يلــزم بإيقــاف النظــر يف دعــوى املدعــى عليهــا لــدى جلنــة‬\n     ‫تســوية املنازعــات املصرفيــة حلــن إنهــاء النــزاع لــدى فضيلتكــم ســيما‬\n     ‫وأن دعوانــا ضــد املدعــى عليهــا أســبق مــن دعواهــا علينــا كمــا تقــدم‬\n     ‫ذكــره أعــاه وذلــك حرص ـ ًا علــى حســن ســير العدالــة وعــدم تضــارب‬\n\n\n‫‪87‬‬\n\f‫األحــكام القضائيــة يف املوضــوع الواحــد‪ .‬ه ــذا واهلل يحفظكــم‬\n‫ويرعاكــم‪ ،‬وبســؤال وكيــل املدعــى عليــه هــل لديــه مــن اجابــه أجــاب‬\n‫بقولــه أكتفــي مبــا ســبق مــن املرافعــة وعليــه فقــد رفعــت اجللســة للتأمــل‬\n‫ثــم يف يــوم األحــد ‪ 1434/03/15‬ه ـ افتتحــت اجللســة الثالثــة الســاعة‬\n‫‪ 10،00‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد جــرى‬\n‫اطالعــي علــى العقــد املبــرم بــن املدعــي والشــركة املدعــي عليهــا‬\n‫فوجدتــه مطبوعــا علــى أوراق مصــرف ‪ .....‬ومعنونــه ب ـ اتفاقيــة تســهيالت‬\n‫ومــؤرخ يف ‪1430/03/25‬ه ـ وأطــراف العقــد هــم مصــرف ‪ .....‬وبــن‬\n‫مؤسســة ‪ .....‬وميثلهــا يف التوقيــع ‪ .....‬ومتضمنــة موافقــة الطــرف األول‬\n‫علــى أن مينــح الطــرف الثانــي حــدا للتعامــل (تســهيالت ) مبلــغ وقــدره‬\n‫‪ 15000000‬خمســة عشــر مليــون ريــال وحصــة املشــاركة ‪ %10‬وهامــش‬\n‫الربــح ‪ %7.5‬ومذيــل بتوقيــع مصــرف ‪ .....‬واملدعــي‪ ،‬وبتأمــل مــا ســبق مــن‬\n‫الدعــوى واإلجابــة وحيــث أن وقائــع الدعــوى تتلخــص يف مطالبــة املدعــي‬\n‫وكالــة إثبــات شــراكة موكلــه مــع شــركة ‪ .....‬املصرفيــة لالســتثمار‬\n‫وحيــث دفــع املدعــى عليــه وكالــة بعــدم االختصــاص كونهــا مــن‬\n‫القضايــا املصرفيــة املنــوط بنظرهــا جلنــة املنازعــات املصرفيــة وحيــث‬\n‫أن االختصــاص مــن أهــم مــا يجــب النظــر فيــه أوال كــون النظــر يف‬\n‫القضايــا أمــر والئــي يعـ ّـد احلكــم عنــد عــدم توفــره باطــا وملــا أن العقــد‬\n‫املبــرم بــن املدعــي واملدعــى عليــه هــو بينــه وبــن مصــرف ‪ .....‬وملــا أن‬\n‫األمــر الســامي الكــرمي رق ـ ــم ‪ 37441‬وتاريــخ ‪1433/08/11‬ه ـ املعمــم‬\n‫م ـ ــن ق ــبل وزيــر الع ـ ــدل ب ـ ــرقم ‪/13‬ت‪ 4708/‬وتاري ـ ــخ ‪1433/09/17‬ه ـ‬\n‫قــد نــص علــى تســمية اللجنــة ب ـ جلنــة املنازعــات املصرفيــة وأنــاط بهــا‬\n‫النظــر يف القضايــا املصرفيــة األصليــة والنظــر يف القضايــا املصرفيــة‬\n\n\n                                                                                       ‫‪88‬‬\n\f     ‫بالتبعيــة وملــا أن التعامــل يف هــذه القضيــة بــن مؤسســة ميثلهــا املدعــي‬\n     ‫وبــن مصــرف ‪ .....‬فهــي مــن القضايــا املصرفيــة وملــا أن مــن عمــل‬\n     ‫املصــارف إعطــاء بعــض العمــاء تســهيالت وفــق شــروط محــددة لــذا‬\n     ‫فقــد رددت دعــوى املدعــي وكالــة لعــدم االختصــاص وبــه حكمــت‬\n     ‫وقــرر املدعــي وكالــة عــدم القناعــة وجــرى تســليمه نســخة احلكــم هــذا‬\n     ‫اليــوم وأفهمتــه مبــدة االعتــراض وأنهــا ثالثــون يومــا مــن تاريخــه وإن‬\n     ‫لــم يعتــرض فيكتســب احلكــم القطعيــة ويصبــح واجــب النفــاذ وقــرر‬\n     ‫املدعــى عليــه وكالــة القناعــة واختتمــت اجللســة الســاعة ‪ 10،30‬وعليــه‬\n     ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم حــرر يف ‪1434/03/15‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض ففــي يــوم اإلثنــن املوافق‪1434/05/20‬ه ـ افتتحــت اجللســة‬\n     ‫الســابعة الســاعة ‪ 9.15‬وفيهــا ورد قــرار محكمــة االســتئناف رقــم‬\n     ‫‪ 34204683‬وتاريــخ ‪1434/05/04‬ه ـ املتضمــن أنــه لم يظهر ما يعترض‬\n     ‫بــه علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/20‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n     ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n     ‫‪ 32731815‬وتاريــخ ‪1434/4/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n     ‫فضيلــة الـ ــقاضي باحملكمــة الشــيخ ‪ ..... /‬املســجل برقــم ‪ .....‬وتاريــخ‬\n     ‫‪1434/3/15‬ه ـ اخلـ ـ ـ ــاص بدعــوى ‪ ..... /‬وكالــة عــن ‪ .....‬ضــد ‪..... /‬‬\n     ‫وكالــة عــن شــركة ‪ .....‬املصرفيــة بشــأن إثبــات شــراكة علــى الصفــة‬\n\n\n‫‪89‬‬\n\f‫املوضحــة بالصــك واملتضمــن أن فضيلتــه رد دعــوى املدعــي وكالــة لعدم‬\n‫االختصــاص وبــه حكــم ‪،‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة قررنــا أنــه لــم يظهــر مــا يعتــرض بــه علــى‬\n‫احلكــم ‪ ،‬والل ــه املوفــق وصلــى اهلل علــى نبينــا محمـ ــد وآل ــه وصحب ــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":78,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3739efbe4c63d20d7b2d3e577e36007e4590e4f8d80343258930d90fce11cd8d","normalized_text_hash":"45791f915ebf4cbf40a090229a8738d1af432ffb3eaf4860d506be25393af8cc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p78-3462403"},{"id":"0d0d03aa-11fb-5e43-98b3-df61f25564e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -ادعاء شراكة عقارية -مطالبة الشريك بنقل ملكية نصيبه يف األرض إليه -بينة غير موصلة -اليمني على نفي الدعوى حق للمدعي وله عدم قبولها -رد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","document_number":"33473259","case_number":"32260602","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/19","year":"1434","subject":"شراكة -ادعاء شراكة عقارية -مطالبة الشريك بنقل ملكية نصيبه يف األرض إليه -بينة غير موصلة -اليمني على نفي الدعوى حق للمدعي وله عدم قبولها -رد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/12/19 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33473259 :‬‬\n                         ‫َر ْق ُم الدعوى‪32260602 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34247114‬تاريخه‪1434/6/20:‬هـ‬\n\n\n      ‫شــراكة ‪ -‬ادعــاء شــراكة عقاريــة ‪ -‬مطالبــة الشــريك بنقــل ملكيــة‬\n      ‫نصيبــه يف األرض إليــه ‪ -‬بينــة غيــر موصلــة ‪ -‬اليمني على نفي الدعوى‬\n      ‫حــق للمدعــي ولــه عــدم قبولهــا‪ -‬رد الدعــوى‪ -‬اســتحقاق املدعــي ليمــن‬\n                              ‫املدعــى عليــه علــى نفــي الدعــوى متــى طلبهــا‪.‬‬\n\n\n\n\n                   ‫قاعدة‪ :‬الدليل إذا تطرق إليه االحتمال بطل به االستدالل‪.‬‬\n\n\n\n\n      ‫ادعى وكيل املدعي أن موكله شــريك للمدعى عليه يف شــراء األرض‬\n      ‫املوصوفــة يف الدعــوى وأنــه قــام بتســليمه املبلــغ املذكــور يف دعــواه نقــد ًا‬\n      ‫ومبوجــب حــواالت مصرفيــة إال أن املدعــى عليــه رفــض إفــراغ نصيــب‬\n      ‫موكلــه مــن تلــك األرض‪ ،‬ولــذا طلــب إلــزام املدعــى عليــه بذلــك وإن‬\n      ‫أنكــره فإنــه يطلــب ميينــه علــى عــدم الشــراكة وإلزامــه بإعــادة املبلــغ‬\n      ‫املســلم لــه‪ ،‬أنكــر وكيــل املدعــى عليــه مــا جــاء يف الدعــوى ودفــع بــأن‬\n      ‫املبالــغ التــي ســلمها املدعــي ملوكلــه هــي إرجــاع جلــزء مــن مبالــغ حولهــا‬\n      ‫املدعــى عليــه قبــل ذلــك حلســاب املدعــي لغــرض تشــغيلها وتوظيفهــا‬\n      ‫يف االســتثمارات العقاريــة‪ ،‬املدعــي لــم يقــدم بينــة علــى الشــراكة‬\n      ‫ســوى احلــواالت املصرفيــة وجميعهــا مؤرخــة بتاريــخ ســابق لتاريــخ وقــت‬\n\n‫‪91‬‬\n\f‫التعاقــد الــذي ذكــره املدعــي مــا عــدا شــيك واحــد ممــا يقــوي أنهــا غيــر‬\n‫متعلقــة مبوضــوع الدعــوى والدليــل إذا تطــرق إليــه االحتمــال بطــل بــه‬\n‫االســتدالل‪ ،‬أفهمــت احملكمــة املدعــي بــأن ملوكلــه ميــن املدعــى عليــه‬\n‫علــى نفــي دعــواه فقــرر عــدم قبــول موكلــه لهــا‪ ،‬قضــت احملكمــة بعــدم‬\n‫اســتحقاق مــا يدعيــه املدعــي جتــاه املدعــى عليــه حــول موضــوع الدعــوى‬\n‫وصرفــت النظــر عــن طلباتــه وأفهمــت املدعــي وكالــة بــأن ملوكلــه ميــن‬\n‫املدعــى عليــه متــى طلبهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n          ‫املدعــي‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫العامــة‬\n   ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة االحســاء برقــم ‪ 32260602‬وتاريــخ ‪1432/7/2‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32812701‬وتاريــخ ‪ 1432/07/02‬ه ـ حضــر‬\n‫ا شــرعي ًا عــن (‪).....‬‬\n                       ‫(‪ ).....‬ســجل مدنــي رقــم (‪ ).....‬حــال كونــه وكي ـ ً‬\n‫ســجل مدنــي رقــم (‪ ).....‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫األحســاء الثانيــة برقــم ‪ 26208‬يف ‪1432/7/5‬ه ـ جلــد ‪ 3831‬والتــي‬\n‫تخولــه هــو والوكيــل الثانــي (‪ ).....‬مجتمعــن أو منفرديــن يف املخاصمــة‬\n‫واملطالبــة واملرافعــة واالقــرار واالنــكار يف الدعــاوى وطلــب اليمــن‬\n‫وغيــر ذلــك وحضــر حلضــوره (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا شــرعي ًا (‪ ).....‬مبوجــب صــك‬   ‫املدنــي رقــم (‪ ).....‬حــال كونــه وكي ـ ً‬\n‫الوكالــة الصــادر مــن كتابــة عــدل األحســاء الثانيــة برقــم ‪ 28384‬يف‬\n‫‪1432/7/19‬ه ـ اجللــد ‪ 3852‬والتــي تخولــه حــق املطالبــة واملرافعــة‬\n\n                                                                                     ‫‪92‬‬\n\f     ‫واملدافعــة وإقامــة الدعــوى وقبــول احلكــم أو االعتــراض عليــه واإلقــرار‬\n     ‫واإلنــكار وغيــر ذلــك وبســؤال املدعــي عــن دعــواه أبــرز ورقــة التالــي‬\n     ‫نصهــا أو ًال ‪ :‬عــرض املدعــى عليــه علــى موكلــي الدخــول معــه يف‬\n     ‫شــراكة لبعــض العقــارات فوافقــه موكلــي ونظــر ًا لوجــود قرابــة وصلــة‬\n     ‫رحــم وللثقــة املتبادلــة فيمــا بينهمــا قــام موكلــي بتســليمه مبالــغ ماليــة‬\n     ‫نقــد ًا ومبوجــب حــواالت بنكيــة وصلــت إجمالهــا مبلغ ـ ًا وقــدره‬\n     ‫(‪ )2.160.000‬مليونــان ومائــة وســتون ألــف ريــال وبالفعــل قــام املدعــى‬\n     ‫عليــه بشــراء األرض الواقعــة (‪ ).....‬مــن القطعــة رقــم ‪ 57‬وحتــى القطعــة‬\n     ‫‪ 68‬باملخطــط رقــم ‪ 180‬وأدخــل موكلــي شــريك ًا فيهــا ‪ .‬ثاني ـ ًا ‪ :‬طلــب‬\n     ‫موكلــي مــن املدعــى عليــه اإلفــراغ لــه يف نصيبــه مــن األراضــي التــي‬\n     ‫أشــركه فيهــا فرفــض املدعــى عليــه ذلــك دون مبــرر شــرعي أو ســبب‬\n     ‫نظامــي وحــاول موكلــي بكافــة الســبل الوديــة احلصــول علــى حقوقــه‬\n     ‫لــدى املدعــى عليــه إال أنــه رفــض وقــام بتهديــده بالشــكوى عليه مبوجب‬\n     ‫شــيكات كانــت لــدى املدعــى عليــه بخصــوص مبالــغ ماليــه ومعامــات‬\n     ‫جتاريــة قدميــة ‪ .‬ثالثـ ًا ‪ :‬تفاجــأ موكلــي بــأن املدعــى عليــه قام بالشــكوى‬\n     ‫علــى موكلــي أمــام وزارة التجــارة مبوجــب هــذه الشــيكات دون مبــرر‬\n     ‫شــرعي أو نظامــي وذلــك بهــدف الضغــط علــى موكلــي للتنــازل عــن‬\n     ‫حقــه يف األراضــي اململوكــة لــه مبوجــب االتفــاق الــذي بينــه وبــن‬\n     ‫املدعــى عليــه مــن شــراكة ‪ .‬لــذا وامتثــاال لقولــه تعالــى ( يــا أيهــا الذيــن‬\n     ‫أمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل إال أن تكــون جتــارة عــن‬\n     ‫تــراض منكــم ) ولقــول الرســول صلــى اهلل عليــه وســلم ( ال ضــرر وال‬\n     ‫ضــرار ) ( والضــرر يــزال ) ‪ .‬أطلــب مــن فضيلتكــم أو ًال ‪ :‬األمــر بوقــف‬\n     ‫النظــر يف الدعــوى املقامــة مــن املدعــى عليــه ضــد موكلــي مبوجــب‬\n\n\n‫‪93‬‬\n\f‫الشــيكات القدميــة وذلــك حلــن الفصــل يف الدعــوى شــرع ًا وموكلــي‬\n‫علــى أمت االســتعداد للمثــول أمــام فضيلتكــم يومـ ًا إلثبــات هــذه الدعــوى‬\n‫‪ .‬ثاني ـ ًا ‪ :‬احلكــم بإلــزام املدعــى عليــه باإلفــراغ ملوكلــي يف العقــار‬\n‫املدعــى بــه التــي أشــرك موكلــي فيهــا فــإن أنكــر ذلــك أطلــب ميــن‬\n‫املدعــى عليــه بأنــه لــم يشــرك موكلــي يف هــذه األراضــي وإلزامــه بإعادة‬\n‫املبلــغ املســلم لــه واهلل املوفــق مقدمــه ‪ .....‬الوكيــل الشــرعي عــن املدعــي‬\n‫ا مــا جــاء يف دعــوى املدعــي‬   ‫وعليــه وبعــرض الدعــوى عليــه أجــاب قائ ـ ً‬\n‫مــن مطالبتــه بإلــزام موكلــي باإلفــراغ لــه يف العقــار املدعــى بــه فغيــر‬\n‫صحيــح واملدعــي ليــس شــريك مــع موكلــي يف األرض الواقعــة (‪ ).....‬مــن‬\n‫القطعــة رقــم ‪ 57‬إلــى القطعــة رقــم ‪ 68‬باملخطــط رقــم ‪ 180‬وأمــا األمــر‬\n‫بوقــف النظــر يف الدعــوى املقامــة يف جلنــة الفصــل فــا يقبــل موكلــي‬\n‫بذلــك هكــذا أجــاب وبســؤال وكيــل املدعــي عن البينة علــى أن األرض‬\n‫محــل الدعــوى هــي شــراكة مــع املدعــى عليــه فأبــرز ورقــة التالــي نصهــا‬\n‫صاحــب الفضيلــة ‪ :‬أفيــد فضيلتكــم باالتــي ‪:‬أو ًال ‪ :‬أن املدعــى عليــه‬\n‫وكالة التزم يف اجللســة الســابقة بتزويدي بنســخة من املذكرة املقدمة‬\n‫مــن قبلــه رد ًا علــى الدعــوى إال أنــه بعــد اجللســة لــم يزودنــي بشــي‪ .‬ثانيـاً‪:‬‬\n‫حيــث أن املدعــى عليــه لــم ينكــر اســتالمه للمبالــغ مــن قبــل موكلــي بــل‬\n‫أخــذ يتحجــج بحجــج واهيــة ويكثــر مــن األوراق املقدمــة مــن جانبــه‬\n‫وذلــك بهــدف إطالــة أمــد التقاضــي قــدر اإلمــكان وهــذا مــن شــأنه‬\n‫إضاعــة وقــت احملكمــة كمــا أن هــذا األمــر يتضــرر منــه موكلــي‬\n‫ضــرر ًا بليغـ ًا والقــول أصبــح يف القضيــة قــول موكلــي لوجــود مســتندات‬\n‫بيــده ‪.‬ثالثـ ًاً‪ :‬حســب وعدنــا لفضيلتكــم نرفــق طيــه نســخة مــن كشــف‬\n‫احلســاب املوضــح بــه إيداعــات املبالــغ يف حســاب املدعــى عليــه أصالــة‬\n\n\n                                                                                          ‫‪94‬‬\n\f     ‫ونفصلهــا كمــا يلــي‪ :‬الســند تاريخــه املبلغ الشــيك رقم (‪ ).....‬واملســحوب‬\n     ‫علــى بنــك (‪ ).....‬الشــيك رقــم (‪ ).....‬واملســحوب علــى بنــك (‪ ).....‬الشــيك‬\n     ‫رقــم (‪ ).....‬واملســحوب علــى بنــك (‪ ).....‬الشــيك رقــم (‪ ).....‬واملســحوب‬\n     ‫علــى بنــك (‪ ).....‬حتويــل للحســاب رقــم ‪ .....‬باســم‪2010/07/24 . .....‬‬\n     ‫‪ 25.000‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪40.000 2010/06/27 . .....‬‬\n     ‫حتويــل للحســاب رقــم ‪ .....‬باســم ‪ 50.000 2010/05/16 . .....‬حتويــل‬\n     ‫للحســاب رقــم ‪ .....‬باســم ‪ 50.000 2010/05/16 . .....‬حتويــل للحســاب‬\n     ‫رقــم ‪ .....‬باســم ‪ 90.000 2010/03 .....‬حتويــل للحســاب رقــم ‪ .....‬باســم‬\n     ‫‪ 60.000 2010/02/04 . .....‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 38.500 2010/06/13‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 300.000 2010/01/21‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 103.200 2009/11/01‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 45.000 2009/07/25‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 200.000 2009/08/05‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪. .....‬‬\n     ‫‪ 66.210 2009/08/22‬حتويــل للحســاب رقــم ‪ .....‬باســم ‪.....‬‬\n     ‫‪ 100.000 2009/07/20‬تســليم املدعــى عليــه اصالــه نقــدا‬\n     ‫‪ 1290 2009/08/22‬إيــداع يف حســاب املدعــى عليــه آصالــه يف مصرف‬\n     ‫(‪ 150.000 2009/11/1 ).....‬مت تســليم املدعــى عليــه أصالــة مبلــغ‬\n     ‫نقــدي باليــد ‪ 240.800 2009/11/1‬املجمــوع ‪ 2.160.000‬ريــال رابعـ ًا‬\n     ‫‪ :‬صاحــب الفضيلــة أؤكــد لفضيلتكــم بــأن املدعــي عليــه أصالــة ‪.....‬‬\n     ‫ميتلــك عقــارات كثيــرة يف األحســاء والدمــام بعضهــا لنفســه وبعضهــا‬\n     ‫اســتثمار ويؤكــد موكلــي لفضيلتكــم بأنــه ليــس لــه أي ملكيــة يف‬\n     ‫تلــك األراضــي وإمنــا حقــه الشــرعي فقــط يف هــذا البلــك املذكــور يف‬\n\n\n‫‪95‬‬\n\f‫الدعــوى وأمــا بالنســبة مللكيتــه يف ذلــك البلــك فهــي بنســبة الثلــث مببلــغ‬\n‫مليونــي ريــال (‪ 2.000.000‬ريــال ) وأمــا املائــة وســتون ألــف ريــال‬\n‫املذكــورة يف الدعــوى فهــي إضافــة خلدمة األراضي والســعي يف شــرائها‬\n‫وفــق مــا أبلــغ بــه املدعــي عليــه أصالــة موكلــي واتفقــا مبوجبــه عليــه‬\n‫أرجــو مــن فضيلتكــم ضبــط مذكرتنــا والفصــل يف الدعــوى بحالتهــا‬\n‫واحلكــم بطلباتنــا الــواردة يف الئحــة حتريــر الدعــوى انتهــى نصهــا ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليــه ‪.....‬‬\n‫ا شــرعي ًا عــن‬ ‫الســعودي بالســجل املدنــي رقــم ‪ .....‬حــال كونــه وكي ـ ً‬\n‫‪ .....‬الســعودي بالســجل املدنــي رقــم ‪ .....‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة عــدل األحســاء الثانيــة برقــم ‪ 16396‬يف ‪1433/4/18‬ه ـ جلــد‬\n‫‪ 4026‬والتــي تخولــه حــق املخاصمــة واملرافعــة واملطالبــة واملدافعــة‬\n‫وإقامــة الدعــوى وقبــول احلكــم أو االعتــراض عليــه والصلــح واإلقــرار‬\n‫واإلنــكار وطلــب اليمــن أو ردهــا واالســتالم والتســليم وبســؤال وكيــل‬\n‫املدعــى عليــه عــن جــواب موكلــه أبــرز ورقــة مكتوبــة ونصهــا (صاحــب‬\n‫الفضيلــة الشــيخ ‪ .....‬القاضــي باحملكمــة العامــة باألحســاء ســلمه اهلل‬\n‫الســام عليكــم ورحمــة اهلل وبركاتــه مذكــرة بالــرد يف الدعــوى‬\n‫املرفوعــة مــن املدعــي ‪ ...../‬ضــد املدعــى عليــه ‪ .....‬صاحــب الفضيلــة‬\n‫حرصـ ًا منــا علــى وقــت فضيلتكــم الثمــن ولعــدم التكــرار فإننــا نحيــل‬\n‫بشــان الوقائــع يف الدعــوى ملــا حتويــه أوراق املعاملــة ومــا ســبق أن قدمنــاه‬\n‫فيهــا مــن مســتندات ومذكــرات ســابقة ونتمســك بــكل مــا جــاء بهــا‬\n‫ونوجــز دفاعنــا يف هــذه املذكــرة علــى بيــان بعــض النقــاط الهامــة والــرد‬\n‫علــى طلــب فضيلتكــم منــا حــول بيــان ســبب احلــواالت التــي حولهــا‬\n‫املدعــي حلســابي وعلــى ذلــك نوجــز الــرد يف التالــي‪1 :‬ـ بالنســبة للمبالــغ‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫احملولــة مــن املدعــي واملودعــة بحســاب املدعــى عليــه البنكــي التــي‬\n     ‫يدعــي املدعــي بأنــه قــد حولهــا للمدعــى عليــه فهــي صحيحــة وال‬\n     ‫ننكرهــا ولكننــا نــود إيضــاح ســببها وهــي أن املدعــي يعمــل يف‬\n     ‫االســتثمارات العقاريــة وكان يســتلم مــن املدعــى عليــه وآخريــن أمــوا ًال‬\n     ‫طائلــة لتوظيفهــا لهــم يف هــذا املجــال بنســبة مرابحــة متغيــرة مــن ‪ % 3‬إلــى‬\n     ‫‪ %3.5‬مــع ضمــان رأس املــال كمــا هــو متفــق عليهــا فيمــا بينهمــا وذلــك‬\n     ‫هــو مــا يفســر حقيقــة األمــوال التــي حولهــا املدعــى عليــه بحســاب املدعي‬\n     ‫‪ ،‬وهــي جميعهــا يف تاريخهــا ســابقة علــى حتويــات املدعــي للمدعــى‬\n     ‫عليــه حيــث اســتلم املدعــي املبالــغ التــي بينهــا املدعــى عليــه باملذكــرات‬\n     ‫ال بكشــوف احلســابات والشــيكات‬            ‫الســابقة املقدمة منه واملبينة تفصي ً‬\n     ‫التــي حررهــا لــه املدعــى عليــه إال أنــه مــع تغيــر الظــروف لــدى املدعــي‬\n     ‫وتعثــره يف ســداد نســب املرابحــة للمدعــى عليــه بــدأت اخلالفــات املاليــة‬\n     ‫بــن الطرفــن تطفــو علــى الســطح وعقــدت فيمــا بينهمــا عــدة جلســات‬\n     ‫للصلــح يف محاولــة مــن املدعــي لتضليــل املدعــى عليــه ومراوغتــه لعــدم‬\n     ‫رد أمــوال املدعــى عليــه إليــه ســواء أصــل املبالــغ التــي ســلمت لــه أو مــا‬\n     ‫نتــج عنهــا مــن أربــاح نتيجــة توظيفهــا لــدى املدعــي ويف ســبيل حل اخلالف‬\n     ‫جزئيـ ًا فقــد قــام املدعــي بتحويــل املبالــغ التــي يدعــي بهــا حلســاب املدعــى‬\n     ‫عليــه كجــزء ممــا يطالبــه بــه مــن أمــوال وليســت كلهــا إال أن املدعــي‬\n     ‫قــد تعثــر كليـ ًا عــن الســداد لباقــي مــا يطالبــه بــه املدعــى عليــه ومــن ثــم‬\n     ‫فمــا كان مــن املدعــى عليــه إال أن أقــام ضــده دعــوى لــدى مكتــب‬\n     ‫الفصــل يف منازعــات األوراق التجاريــة يطالبــه فيهــا بإلزامــه بدفــع قيمــة‬\n     ‫بعــض الشــيكات مــن تلــك املبالــغ املســلمة للمدعــي لتوظيفهــا وقــد‬\n     ‫صــدر بالفعــل ضــده حكــم يف تلــك الدعــوى إال أن املدعــي ويف رد فعــل‬\n\n\n‫‪97‬‬\n\f‫انتقامــي منــه ضــد املدعــى عليــه فقــد اصطنــع هــذه الدعــوى املنظــورة‬\n‫أمــام فضيلتكــم بتدبيــر مــن بعــض ممــن يوعــز إليــه مبثــل ذلــك الســلوك‬\n‫هادفــا منهــا تضليــل العدالــة والتلبيــس عليهــا مدعيـ ًا علــى غيــر احلقيقــة‬\n‫بأنــه ســلم املدعــى عليــه تلــك املبالــغ لشــراء البلــك الكائــن (‪ ).....‬وهــو‬\n‫مــا لــم يحــدث حقيقــة وســوف نوضــح لفضيلتكــم عــدم صحــة مــا يدعيه‬\n‫يف هــذا األمــر ولكــن تبقــى احلقيقــة الثابتــة هــي كــون تلــك املبالــغ التــي‬\n‫حولــت مــن قبــل املدعــي بحســاب املدعــى عليــه هــي نــاجت إرجــاع جلــزء مــن‬\n‫مبالــغ حولهــا املدعــى عليــه حلســاب املدعــي لتشــغيلها وتوظيفهــا بنســبة‬\n‫مرابحــة ويف هــذا الصــدد نطلــب مــن فضيلتكــم التكــرم مبخاطبــة‬\n‫مؤسســة ‪ .....‬الســعودي للوقــوف علــى حقيقــة املبالــغ البينيــة احملولــة‬\n‫واملدفوعــة بــن الطرفــن وعلــى ذلــك فالثابــت حقيقــة أن املدعــي هــو مــن‬\n‫كان يقــوم بتوظيــف أمــوال املدعــى عليــه يف االســتثمار العقــاري وليــس‬\n‫العكــس كمــا يدعــي املدعــي بدعــواه زور ًا ولدينــا مــن البينــات علــى‬\n‫ذلــك مــا يكفــي مــن شــهادة شــهود نطلــب ســماع شــهادتهم يف هــذا‬\n‫الصــدد ورســائل اجلــوال الصــادرة مــن املدعــي مــن جوالــه اخلــاص جلــوال‬\n‫املدعــى عليــه تفيــد وتقطــع بذلــك ‪2‬ـ أمــا مــن حيــث مــا يدعيــه املدعــي‬\n‫كذبـ ًا بأنــه قــد ســلم املدعــى عليــه املبالــغ التــي يدعــي بهــا لشــراء البلــك‬\n‫الكائــن (‪ ).....‬اجلنوبيــة باألحســاء فإننــي بدايــة أود توضيــح حقيقــة‬\n‫لفضيلتكــم أن ذلــك الزعــم مــن قبــل املدعــي هــو محض افتــراء وكذب‬\n‫وتلبيــس علــى احملكمــة يقــوم بــه املدعــي يف هذا الصــدد حيث ال عالقة‬\n‫لــه مــن قريــب أو بعيــد وال عالقــة باملبالــغ التــي يدعــي بهــا بهــذا البلــك‬\n‫إطالق ـ ًا كمــا ســبق وان بينــا لفضيلتكــم ســبب تلــك املبالــغ وملــاذا‬\n‫ســلمها املدعــي للمدعــى عليــه ومــن كونهــا إرجــاع جلــزء مــن أصــل مــا‬\n\n\n                                                                                          ‫‪98‬‬\n\f     ‫يطالبــه بــه املدعــى عليــه مــن مبالــغ ثابتــة مبوجــب شــيكات محــررة منــه‬\n     ‫للمدعــى عليــه بــل أن البلــك املذكــور قــد قــام املدعــى عليــه بشــرائه مــع‬\n     ‫شــريكني آخريــن همــا املدعــو ‪ .....‬و‪ .....‬بحصــة الثلــث لــكل منهــم يف‬\n     ‫ملكيــة ذلــك البلــك وذلــك ألجــل اســتثماره وإعــادة بيعــه وقــد قامــوا‬\n     ‫بتحريــر عقــد اســتثمار عقــاري فيمــا بينهــم عــن ذلــك البلــك يف تاريــخ‬\n     ‫‪1431/4/1‬ه ـ ( مرفــق صورتــه بهــذه املذكــرة ) وذلــك إلثبــات شــراكة‬\n     ‫الشــركاء فيــه كونــه قــد مت إفراغــه وتســجيله رســمي ًا باســم املدعــى‬\n     ‫عليــه فقــط ولــم يذكــر يف الصــك اســم شــريكيه اآلخريــن فيــه وعلــى‬\n     ‫ذلــك مت حتريــر ذلــك العقــد فيمــا بينهــم ‪ ،‬إال أن املفاجــأة التــي قــد تذهــل‬\n     ‫املدعــي يف هــذه الدعــوى وتكشــف مــا يدعيــه كذبـ ًا انــه وبالرغــم مــن‬\n     ‫مشــاركة املدعــى عليــه يف هــذا البلــك لشــركائه املذكوريــن وإفــراغ‬\n     ‫بالبلــك بالكامــل باســمه إال أن متويــل حصــة املدعــى عليــه فيهــا والبالــغ‬\n     ‫ا ولكنها‬     ‫قدرهــا الثلــث وملكيتــه لهــذه احلصــة لــم تكــن عائــدة لــه فعـ ً‬\n     ‫تعــود ملكيتهــا احلقيقيــة ملؤسســة ‪ .....‬العقاريــة والــذي مت تفويضــه مــن‬\n     ‫قبــل املؤسســة املذكــورة بشــراء تلــك احلصــة وإفــراغ البلــك باســمه‬\n     ‫الشــخصي كونــه أحــد الشــركاء املســاهمني يف هــذه املؤسســة وقــد مت‬\n     ‫متويــل تلــك احلصــة ودفــع قيمتهــا للمدعــى عليــه مــن احلســاب البنكــي‬\n     ‫كل مــن‪..... /3 ..... /2 ..... /1‬‬   ‫اخلــاص للمؤسســة واملســجل بأســماء ٍ‬\n     ‫مبوجــب الشــيك املصــريف رقــم ‪ 2065854‬وتاريــخ ‪1431/3/10‬ه ـ‬\n     ‫واملســحوب علــى بنــك ‪( .....‬مرفــق صــورة الشــيك وأمــر للبنــك املذكــور‬\n     ‫بإصــدار شــيك مصــدق للمدعــى عليــه ) مببلــغ وقــدره ‪ 1.800.000‬ريــال‬\n     ‫(مليــون وثمامنائــة ألــف ريــال )والــذي صرفــه املدعــى عليــه وأضــاف عليــه‬\n     ‫حصتــه كشــريك وقــام بدفــع قيمــة تلــك احلصــة ملالــك العقــار مبوجــب‬\n\n\n‫‪99‬‬\n\f‫الشــيك املصــدق رقــم ‪ 007540‬وتاريــخ ‪1431/3/13‬ه ـ واملســحوب علــى‬\n‫بنــك (‪ ( ).....‬مرفــق صورتــه بهــذه املذكــرة ) واملبــن بــه بأنــه مقابــل‬\n‫بلــوك (‪ ).....‬مببلــغ وقــدره ‪2.021.500‬ريــال مليونــان وواحــد وعشــرون‬\n‫ألف ـ ًا وخمســمائة ريــال وهــي ذات قيمــة احلصــة البالــغ قدرهــا الثلــث‬\n‫املبينــة بعقــد االســتثمار للعقــار املرفــق بهــذه املذكــرة ‪ ،‬ومــن ثــم فإنــه‬\n‫يتبــن لفضيلتكــم أنــه لــم يكــن املدعــى عليــه يف احلقيقــة هــو املالــك‬\n‫للبلــك الــذي ادعــى املدعــي أنــه قــام بتحويــل تلــك املبالــغ حلســاب املدعــى‬\n‫عليــه لشــرائه علــى غيــر احلقيقــة وأن تلــك احلصــة يف البلــك تعــود‬\n‫ملكيتهــا احلقيقيــة ملؤسســة (‪).....‬العقاريــة وليــس املدعــى عليــه وأنــه مت‬\n‫متويلهــا مــن أمــوال تلــك املؤسســة ومــن حســابها كمــا هــو ثابــت‬\n‫بالشــيكات املرفقــة بــل أنــه لدينــا شــهود مــن الشــركاء يف املؤسســة‬\n‫واملســاهمني فيهــا ومــن ذات أبنــاء عائلــة (‪ ).....‬وكبــار رجاالتهــا الســيما‬\n‫وأن موضــوع الدعــوى كان يتصــف خبــره بــن أبنــاء العائلــة بالشــياع‬\n‫للجميــع بأنــه يخــص املســاهمني يف مؤسســة (‪ ).....‬العقاريــة التــي ينتمــي‬\n‫لهــا طــريف الدعــوى املدعــي واملدعــى عليــه مســتعدون للشــهادة حــول‬\n‫موضــوع البلــك وملــن تعــود ملكيتــه وكافــة التفاصيــل اخلاصــة بــه‬\n‫وأيض ـ ًا حــول العالقــة املاليــة بــن املدعــي واملدعــى عليــه ونطلــب مــن‬\n‫فضيلتكــم ســماع شــهادتهم يف هــذا اخلصــوص لكشــف وبيــان احلقيقــة‬\n‫ـاء‬\n‫يف الدعــوى ومــا يدعيــه املدعــي فيهــا زور ًا وبهتانـ ًا صاحــب الفضيلــة بنـ ً‬\n‫علــى مــا تقــدم فإننــي أتوجــه لفضيلتكــم بالتكــرم بفحــص البينــات‬\n‫املقدمــة مــن املدعــى عليــه يف هــذه الدعــوى وســماع شــهادة الشــهود فيهــا‬\n‫كزيــادة بينــة علــى عــدم صحــة دعــوى املدعــى وأطلــب مــن فضيلتكــم‬\n‫بعــد نظــر الدعــوى علــى الوجــه الشــرعي وحتقيقهــا صــرف النظــر عــن‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫دعــوى املدعي)‪.‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــي وكالــة أجــاب بقولــه ال‬\n      ‫صحــة ملــا ذكــر يف مذكــرة املدعــى عليــه وممــا يؤكــد صحــة دعــوى‬\n      ‫موكلــي مــا يلــي‪ :‬أوالً‪ :‬إن املدعــى عليــه أصالــة أقــر بوجــود عقــارات‬\n      ‫بينــه وبــن موكلــي مشــاركة ثاني ـاً‪ :‬عندمــا ســأل املدعــى عليــه عــن‬\n      ‫املبالــغ التــي أودعــت يف حســابه مــن قبــل موكلــي طلــب تأجيــل الدعــوى‬\n      ‫ولــو كان مــا يدعيــه صحيــح لذكــره علــى الفــور لكنــه اســتمهل أيضـ ًا‬\n      ‫ولــم يجــب إال يف اجللســة الرابعــة ثالثـاً‪ :‬موكلــي ال يعلــم عــن هــذا البلــوك‬\n      ‫إال مــن ابــن عمــه املدعــى عليــه أصالــة لكونــه مــن أبلغــه بالعــرض‬\n      ‫املوجــود وأنــه يطلــب أن يشــاركه يف هــذا البلــك وهــذا بنــاء علــى قــول‬\n      ‫املدعــى عليــه أصالــة رابعـاً‪ :‬قــدم املدعــى عليــه يف مذكرتــه أنــه يطلــب‬\n      ‫احلكــم بعــدم االختصــاص فقــط ولــو كان صاحــب حــق لذكــر املبلــغ‬\n      ‫ال دون‬   ‫وطالــب باحلكــم بــه لكنــه حــرص علــى احلكــم باملبلــغ شــك ً‬\n      ‫الدخــول يف املوضــوع مــن خــال وزارة التجــارة هكــذا أجــاب وعليــه‬\n      ‫وبتأمــل مــا ســبق جــرى ســؤال املدعــي وكالــة هــل اســتلم موكلــه أمــوا ًال‬\n      ‫مــن املدعــى عليــه يف الســابق لغــرض االســتثمار لــه فقــال لــم يحصــل‬\n      ‫ذلــك كمــا جــرى ســؤال املدعــى عليــه نفــس هــذا الســؤال وهــل اســتلم‬\n      ‫أمــوال مــن املدعــي لغــرض االســتثمار لــه فقــال نعــم توجــد تعامــات بــن‬\n      ‫الطرفــن وســبق وأن اســتلم موكلــي أمــوال مــن املدعــي لغــرض‬\n      ‫االســتثمار ســابقة عــن موضــوع الدعــوى وســلم لــه أمــوا ًال هكــذا أجــاب‬\n      ‫فجــرى ســؤال املدعــي هــل هنــاك عقــد بــن موكلــه واملدعــى عليــه حــول‬\n      ‫موضــوع الدعــوى فقــال أطلــب الرجــوع ملوكلــي كمــا جــرى ســؤال‬\n      ‫املدعــى عليــه وكالــة هــل يوجــد عقــد بــن موكلــه واملدعــى عليــه علــى‬\n      ‫شــراكتهما غيــر موضــوع الدعــوى فقــال أطلــب الرجــوع ملوكلــي كمــا‬\n\n\n‫‪101‬‬\n\f‫جــرى ســؤال املدعــى عليــه هــل البلــك محــل الدعــوى ال يــزال ملــك‬\n‫ملوكلــه فقــال إن موكلــي قــد تصــرف بهــذا البلــك بالبيــع كما ذكرت‬\n‫ســابقا يف جوابــي علــى الدعــوى كمــا جــرى ســؤال املدعــي وكالــة عــن‬\n‫تاريــخ التعاقــد بــن موكلــه واملدعــى عليــه حــول هــذا البلــك محــل‬\n‫الدعــوى فقــال أطلــب الرجــوع ملوكلــي ويف جلســة أخــرى أبــرز املدعــي‬\n‫وكالــة جوابـ ًا علــى االستفســارات املوجهــة ملوكلــه مــن قبــل احملكمــة‬\n‫ا بخصــوص استفســاركم هــل اســتلم‬             ‫يف اجللســة املاضيــة فأجــاب قائ ـ ً‬\n‫موكلــي أمــوا ًال مــن املدعــى عليــه يف الســابق لغــرض االســتثمار لــه فهــذا‬\n‫غيــر صحيــح وأمــا عــن وجــود تعاقــد أو عقــد مكتــوب حــول موضــوع‬\n‫الدعــوى فأجيــب بأنــه ال يوجــد عقــد بــن الطرفــن علــى هــذه األرض‬\n‫محــل الدعــوى واكتفــى موكلــي بدفــع املبلــغ نظــر ًا لصلــة الرحــم التــي‬\n‫بينهمــا وأمــا عــن تاريــخ التعاقــد حــول األرض محــل الدعــوى فأجيــب أنــه‬\n‫مت العــرض مــن قبــل املدعــى عليــه ملوكلــي بالدخول معــه يف هذه األرض‬\n‫شــريك ًا وذلــك بنهايــة شــهر صفــر لعــام ‪1431‬ه ـ بعــد أن وقــف موكلــي‬\n‫علــى األرض وعاينهــا قبــل الدخــول يف الشــراكة هــذا هــو جوابــي علــى‬\n‫مــا طلــب مــن موكلــي كمــا أبــرز املدعــى عليــه وكالــة جواب ـ ًا علــى‬\n‫ا‬\n‫االستفســارات املوجهــة ملوكلــه مــن قبــل احملكمــة فأجــاب قائ ـ ً‬\n‫صاحــب الفضيلــة حرص ـ ًا منــا علــى وقــت فضيلتكــم الثمــن ولعــدم‬\n‫التكــرار فإننــا نحيــل بشــان الوقائــع يف الدعوى ملا حتويــه أوراق املعاملة‬\n‫ومــا ســبق ان قدمنــاه فيهــا مــن مســتندات ومذكــرات ســابقة ونتمســك‬\n‫بــكل مــا جــاء بهــا ونوجــز دفاعنــا يف هــذه املذكــرة علــى بيــان بعــض‬\n‫النقــاط الهامــة حــول طبيعــة العالقــة املاليــة بــن طــريف الدعــوى وهــي‬\n‫كالتالــي ‪:‬املدعــي كان يعمــل يف مجــال مضاربــات االســتثمار العقــاري‬\n\n\n                                                                                       ‫‪102‬‬\n\f      ‫مــن خــال الشــركة التــي ميلكهــا ابــن عمــه ‪ /‬املدعــو ‪ .....‬وآخــر‬\n      ‫واملعروفــة باســم شــركة ‪ ..... .....‬لالســتثمارات العقاريــة وكان املدعــي‬\n      ‫أحــد املتعاملــن مــع هــذه الشــركة وكان يقــوم بجمــع أمــوال مــن‬\n      ‫الكثيــر مــن أبنــاء العائلــة وغيرهــم الســتثمارها مــن خــال مــا تقــوم بــه‬\n      ‫هــذه الشــركة مــن مضاربــات ‪ ،‬كمــا أن املدعــي ونظــر ًا لطبيعــة عملــه‬\n      ‫كان يتعثــر يف بعــض األحيــان ويطلــب مــن املدعــى عليــه إقراضــه‬\n      ‫بقــروض حســنة ‪ ،‬ونظــر ًا لصلــة القرابــة والعالقــة الشــخصية والثقــة‬\n      ‫املتبادلــة فقــد كان املدعــى عليــه يقــرض املدعــي الكثيــر مــن االمــوال‬\n      ‫كقــرض حســنة ‪ ،‬إلــى أن عــرض املدعــي علــى املدعــى عليــه أن يقــوم‬\n      ‫املدعــى عليــه بدفــع مبالــغ لــه ليقــوم باســتثمارها لصاحلــه ‪ ،‬كمــا عــرض‬\n      ‫عليــه جمــع مبالــغ مــن أيــة أشــخاص آخريــن يعرفهــم ليقــوم املدعــي‬\n      ‫باســتثمارها لهــم مــن خــال الشــركة املذكــور وذلــك نظيــر نســبة‬\n      ‫مرابحــة وعلــى أن يكــون التعامــل قاصــر ًا فيمــا بــن املدعــي واملدعــى‬\n      ‫عليــه فقــط ‪ ،‬ولذلــك كان املدعــى عليــه يســلم املدعــي مبالــغ ملــدد‬\n      ‫محــددة يقــوم خــال تلــك املــدة باملضاربــة يف تلــك األمــوال وعلــى أن يعيــد‬\n      ‫لــه أصــل املبلــغ يف خــال األجــل املتفــق عليــه فيمــا بينهمــا ‪ ،‬إلــى أن‬\n      ‫تعثــرت الشــركة املذكــورة لوجــود خالفــات ماليــة بــن أطرافهــا‪ ،‬فبدأ‬\n      ‫املدعــي باســتالم املبالــغ اخلاصــة باملدعــى عليــه وآخريــن دون إرجاعهــا ال‬\n      ‫أصــل املبلــغ وال نســبة املرابحــة املتفــق عليهــا ممــا حــدا باملدعــى عليــه‬\n      ‫إلقامــة دعــوى ضــده لــدى وزارة التجــارة للمطالبــة بقيمــة بعــض املبالــغ‬\n      ‫التــي اســتلمها املدعــي وحــرر عنهــا شــيكات لصالــح املدعــى عليــه‬\n      ‫وصــدر ضــد املدعــي حكــم فيهــا ‪ ،‬قــد اصطنــع هــذه الدعــوى املنظــورة‬\n      ‫امــام فضيلتكــم بتدبيــر مــن بعــض ممــن يوعــز إليــه مبثــل ذلــك الســلوك‬\n\n\n‫‪103‬‬\n\f‫هادفـ ًا منهــا تضليــل العدالــة و التلبيــس عليهــا مدعيـ ًا علــى غيــر احلقيقــة‬\n‫بأنــه ســلم املدعــى عليــه تلــك املبالــغ لشــراء البلــك الكائــن (‪ ).....‬وهــو ما‬\n‫لــم يحــدث حقيقــة وهــو محــض افتــراء وكــذب وتلبيــس علــى احملكمــة‬\n‫يقــوم بــه املدعــي يف هــذا الصــدد حيــث ال عالقــة لــه مــن قريــب أو بعيــد‬\n‫وال عالقــة باملبالــغ التــي يدعــي بهــا بهــذا البلــك إطالق ـ ًا ‪ ،‬وذلــك كمــا‬\n‫ســبق وان بينــا يف مذكرتنــا الســابقة ‪ ،‬ويوجــد لــدى املدعــى عليه شــهود‬\n‫مــن كبــار العائلــة مســتعدون للشــهادة حــول موضــوع البلــك وملــن تعــود‬\n‫ملكيتــه واملعامــات املاليــة بــن طــريف الدعــوى وطبيعتهــا وحقيقتهــا‬\n‫ونتمســك امــام فضيلتكــم ســماع شــهادتهم يف هــذا اخلصوص لكشــف‬\n‫وبيــان احلقيقــة يف الدعــوى ومــا يدعيــه املدعــي فيهــا زور ًا وبهتانـاً‪ .‬وأمــا‬\n‫مــن حيــث وجــود شــراكة فيمــا بــن املدعــي واملدعــى عليــه يف ذلــك‬\n‫البلــك أو أيــة شــراكة أخــرى فــا توجــد فيمــا بينهمــا أيــة شــراكة مــن‬\n‫أي نــوع ولــم يقــم املدعــى عليــه بتحريــر أيــة عقــود شــراكة فيمــا بينــه‬\n‫وبــن املدعــي ألي نــوع مــن الشــراكة يف أي وقــت مضــى علــى إقامــة‬\n‫ـاء علــى مــا تقــدم فإننــي أتوجــه‬ ‫هــذه الدعــوى‪ ،‬صاحــب الفضيلــة‪ :‬بنـ ً‬\n‫لفضيلتكــم بالتكــرم بســماع شــهادة الشــهود يف الدعــوى كزيــادة‬\n‫بينــة علــى عــدم صحــة دعــوى املدعــى وأطلــب مــن فضيلتكــم بعــد نظــر‬\n‫الدعــوى علــى الوجــه الشــرعي وحتقيقهــا صــرف النظــر عــن دعــوى‬\n‫املدعــي وملــا كانــت دعــوى املدعــي ضــد املدعــى عليــه متعلقــة مببلــغ‬\n‫وقــدره مليونــان ومائــة وســتون ألــف ريــال لقاء شــراكة يف بلــك األراضي‬\n‫املوصوفــة يف الدعــوى وأنــه قــام بتحويــل هــذا املبلــغ يف حســاب املدعــى‬\n‫عليــه لذلــك الغــرض وأنكــر املدعــى عليــه أنــه اتفــق مــع املدعــي علــى‬\n‫الدخــول يف شــراكة حــول األراضــي املذكــورة وأنــه اســتلم املبلــغ‬\n\n\n                                                                                         ‫‪104‬‬\n\f      ‫املذكــورة لذلــك الغــرض وصــادق علــى أن املدعــي قــد حــول لــه املبلــغ‬\n      ‫املدعــى بــه ودفــع بــأن هــذه املبالــغ متعلقــة بنشــاط آخــر ال عالقــة لــه‬\n      ‫باألراضــي محــل الدعــوى وإمنــا ناجتــة عــن اســتثمارات أخرى بــن املدعي‬\n      ‫واملدعــى عليــه ومــا حولــه املدعــي يف حســاب املدعــى عليــه هــي نــاجت هــذه‬\n      ‫االســتثمارات وأقــر املدعــي بعــدم وجــود عقــد مــع املدعــى عليــه ينظــم‬\n      ‫العالقــة العمليــة بينهمــا وأقــر بعــدم وجــود تعامــات مــع املدعــى عليــه‬\n      ‫غيــر موضــوع البلــك محــل الدعــوى وأنكــر أخــذه أمــوال مــن املدعــى‬\n      ‫عليــه لغــرض االســتثمار فيهــا ولــم يصادقــه املدعــى عليــه علــى ذلــك‬\n      ‫ونظــر ًا لكــون دعــوى املدعــي مقصــورة علــى موضــوع البلــك محــل‬\n      ‫الدعــوى وبينتــه هــي احلــواالت وقــد قــرر املدعــي أن الشــراكة يف البلــك‬\n      ‫حصلــت بنهايــة شــهر صفــر مــن عــام ‪1431‬ه ـ وبالرجــوع لهــذه احلــواالت‬\n      ‫وجدتهــا جميعـ ًا مؤرخــة بتاريــخ ســابق لتاريــخ وقــت التعاقــد حــول البلــك‬\n      ‫الــذي ذكــره املدعــي مــا عــدا شــيك واحــد مببلــغ مائــة وثالثــن ألــف‬\n      ‫ريــال ممــا يقــوي أن هــذه احلــواالت غيــر متعلقــة مبوضــوع الدعــوى ويؤيــد‬\n      ‫أن هنــاك تعامــات بــن الطرفــن أخــرى ســابقة ملوضــوع الدعــوى‬\n      ‫ويؤكــد ذلــك القــرارات الصــادرة مــن وزارة التجــارة ممــا يــدل علــى‬\n      ‫عــدم صحــة مــا ذكــره املدعــي مــن عــدم وجــود تعامــل مــع املدعــى عليــه‬\n      ‫ا‬\n      ‫غيــر موضــوع الدعــوى ومبوجــب ذلــك فــإن مجــرد احلــواالت ليســت دليـ ً‬\n      ‫علــى صحــة دعــوى املدعــي ألن وجــود التعامــات الســابقة يضعــف تعلــق‬\n      ‫احلــواالت مبوضــوع الدعــوى والقاعــدة الشــرعية تقــول إن الدليــل إذا‬\n      ‫تطــرق إليــه االحتمــال بطــل بــه االســتدالل وال بينــة أخــرى لــدى املدعــي‬\n      ‫علــى صحــة دعــواه لــذا فقــد أفهمــت املدعــي وكالــة بــأن ليــس ملوكلــه‬\n      ‫ســوى ميــن املدعــى عليــه أصالــة علــى نفــي دعــواه فأجــاب بقولــه إن‬\n\n\n‫‪105‬‬\n\f‫موكلــي يرفــض ميــن املدعــى عليــه فبنــاء علــى مــا تقــدم كلــه فقــد‬\n‫حكمــت بعــدم اســتحقاق مــا يدعيــه املدعــي جتــاه املدعــى عليــه حــول‬\n‫موضــوع الدعــوى وصرفــت النظــر عــن طلباتــه وأفهمــت املدعــي وكالــة‬\n‫بــأن ملوكلــه ميــن املدعــى عليــه متــى طلبهــا وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر القناعــة بــه وأمــا املدعــي وكالــة فقــرر املعارضــة‬\n‫عليــه فأفهمتــه مبراجعتنــا بعــد إجــازة عيــد األضحــى املبــارك بتاريــخ‬\n‫‪1433/12/18‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي املعارضــة عليــه‬\n‫خــال املــدة النظاميــة وهــي ثالثــون يوم ـ ًا فــإذا انتهــت هــذه املــدة دون‬\n‫تقــدمي االعتــراض فســوف يســقط حقــه يف املعارضــة ويكتســب احلكــم‬\n‫القطعيــة مبوجبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/23‬ه ـ يف متــام الســاعة الواحــدة‬\n                                                                            ‫ظهرا ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد وردت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية برقــم ‪ 34273261‬تاريــخ ‪1434/3/23‬ه ـ واملقيــدة‬\n‫بهــذه احملكمــة برقــم ‪ 34/768027‬تاريــخ ‪1434/3/28‬ه ـ وبرفقهــا‬\n‫القــرار الصــادر مــن أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى‬\n‫رقــم ‪ 3465176‬تاريــخ ‪1434/3/17‬ه ـ نــص املقصــود منــه بدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n‫أن املدعــي يطالــب بإعــادة املبلــغ الــذي أقــر املدعــى عليــه باســتالمه ‪،‬‬\n‫فعلــى فضيلتــه إجــراء اإليجــاب الشــرعي حيــال ذلــك ‪ ،‬وإكمــال الــازم‬\n‫حســب التعليمــات ‪ ،‬واهلل املوفــق قضــاة محكمــة االســتئناف وهــم ‪َ .....‬و‬\n‫د‪َ ..... .‬و رئيــس الدائــرة ‪ .....‬وعليــه توقيــع وختــم لــكل واحــد منهــم وعليــه‬\n‫أجيــب أصحــاب الفضيلــة بــأن مجــرد اســتالم املدعــى عليــه للمبلــغ ال‬\n\n\n                                                                                        ‫‪106‬‬\n\f      ‫يلــزم منــه أنــه متعلــق مبوضــوع الدعــوى حيــث إن موضــوع الدعــوى‬\n      ‫خــاص بنــزاع حــول مجموعــة أراضــي يف بلــك يقــع يف (‪ ).....‬واحلكــم‬\n      ‫متعلــق بــه وليــس متعلقـ ًا بالتعامــات األخــرى التــي بني الطرفــن وال يلزم‬\n      ‫مــن احلكــم بصــرف النظــر حــول هــذه الدعــوى عــدم أحقيــة املدعــي يف‬\n      ‫إقامــة دعــاوى أخــرى متعلقــة بالتعامــات املاليــة األخــرى حســب القواعد‬\n      ‫املعتبــرة يف إقامــة الدعــاوى بعــد حتريرهــا وتفصيلهــا وبيانهــا وال يلزمنــي‬\n      ‫أن أنظــر يف جميــع التعامــات املاليــة التــي بــن الطرفــن وأن أدخلهــا يف‬\n      ‫هــذه الدعــوى ألن احلكــم يجــب أن يكــون مالقي ـ ًا للدعــوى ومتعلق ـ ًا‬\n      ‫بهــا لــذا فليــس لــدي ســوى مــا حكمــت بــه وأمــرت بإحلــاق ذلــك بصكــه‬\n      ‫وســجله وإعــادة املعاملــة حملكمــة االســتئناف إلجــراء مــا يرونــه وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪1434/4/15‬هــ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34247114‬وتاريــخ‬\n                                                       ‫‪1434/6/20‬هـ‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":91,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"258787ca0f32444c3968145c9b57c28431c1983645ec132e40fc482bca76c4d1","normalized_text_hash":"0be5251fbb2054e3ae76d84e3a00c42015240a450f6db7476ed9a0496ee412bc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p91-33473259"},{"id":"8b7e607d-cfe5-5822-b308-8dfd9c87191a","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة جتارية -حوالة -إيداع املبلغ املدعى به مبوجب حتويل بنكي -الدفع بان املبالغ املودعة جرى تسليمها لشخص آخر -إذا اختلف الدافع والقابض يف صفة املقبوض فالقول قول الدافع مع ميينه -احلوالة بناء على طلب شخص غير احملول له -إلزام املدعى عليه بدفع املبلغ محل الدعوى.","document_number":"33354636","case_number":"32403744","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/20","year":"1434","subject":"شراكة جتارية -حوالة -إيداع املبلغ املدعى به مبوجب حتويل بنكي -الدفع بان املبالغ املودعة جرى تسليمها لشخص آخر -إذا اختلف الدافع والقابض يف صفة املقبوض فالقول قول الدافع مع ميينه -احلوالة بناء على طلب شخص غير احملول له -إلزام املدعى عليه بدفع املبلغ محل الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33354636 :‬‬\n                   ‫َر ْق ُم الدعوى‪32403744 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34179689‬تاريخه‪1434/4/6:‬هـ‬\n\n\n‫شــراكة جتاريــة‪ -‬حوالــة ‪ -‬إيــداع املبلــغ املدعــى بــه مبوجــب حتويــل‬\n‫بنكــي ‪ -‬الدفــع بــان املبالــغ املودعــة جــرى تســليمها لشــخص آخــر ‪ -‬إذا‬\n‫اختلــف الدافــع والقابــض يف صفــة املقبــوض فالقــول قــول الدافــع مــع‬\n‫ميينــه ‪ -‬احلوالــة بنــاء علــى طلــب شــخص غيــر احملــول لــه ‪ -‬إلــزام‬\n                               ‫املدعــى عليــه بدفــع املبلــغ محــل الدعــوى‪.‬‬\n\n\n\n‫قاعــدة‪ :‬إذا اختلــف الدافــع والقابــض يف صفــة املقبــوض فالقــول قــول‬\n                                                    ‫الدافــع مــع ميينــه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــان املدعــى عليــه أصالــة قــام بإرســال مندوبــه‬\n‫ومكفولــة إلــى موكلــه وعــرض عليــه أعمــاال جتاريــة علــى ســبيل‬\n‫الشــراكة ‪ -‬قــرر املدعــي وكالــة بــأن املدعــى عليــه أصالــة اســتلم مــن‬\n‫موكلــه مبلغــا قــدره ســتمائة وســبعون ألــف ريــال أودعــت بحــواالت‬\n‫بنكيــة يف حســاب املدعــى عليــه ‪ .‬عنــد مطالبــة املدعــى عليــه أفــاد‬\n‫بــأن مكفولــه شــخص نصــاب وأنــه هــرب إلــى بــاده باألمــوال طلــب‬\n‫املدعــي وكالــة إلــزام املدعــي عليــه أصالــة بإعــادة املبلــغ املذكور أجاب‬\n‫املدعــى عليــه وكالــة بــأن الوافــد املذكــور ليــس مندوبــا ملوكلــه وإمنــا‬\n\n                                                                                   ‫‪108‬‬\n\f      ‫يعمــل حتــت كفالتــة ولــم يرســله موكلــه للمدعــى أصالــة ليعــرض عليــه‬\n      ‫أعمــاال جتاريــة وان موكلــه ال يعــرف املدعــي أصالــة وأمــا التحويــات‬\n      ‫البنكيــة فــإن املبلــغ املدعــى بــه قــد مت حتويلــه حلســاب مؤسســة موكلــه‬\n      ‫لصالــح مكفــول موكلــه املذكــور ‪ ،‬حيــث ذكــر مكفــول موكلــه‬\n      ‫بــأن لــه يف ذمــة شــخص املبلــغ املدعــى بــه وأنــه اتفــق معــه علــى حتويــل‬\n      ‫هــذا املبلــغ حلســاب موكلــه خشــية من املســائلة من الدوائــر املختصة ألن‬\n      ‫املبلــغ كبيــر ‪ ،‬وأن موكلــه بعــد دخــول املبلــغ حلســابه قــام بســحب هــذا‬\n      ‫املبلــغ وتســليمه ملكفولــه املذكــور عــد ًا ‪ .‬طلــب املدعــى عليــه وكالــة‬\n      ‫رد دعــوى املدعــي وإفهامــه بإقامــة دعــواه علــى املكفــول املذكــور‬\n      ‫أبــرز املدعــى عليــه إقــرار ًا منســوبا ملكفولــه املذكــور بــأن يف ذمــة‬\n      ‫هــذا املكفــول للمدعــى أصالــة املبلــغ املدعــى بــه‪ -‬حلــف املدعــي أصالــة‬\n      ‫اليمــن علــى صحــة دعــواه حيــث أقــر املدعــى عليــه بإيــداع املبلــغ املدعى‬\n      ‫بــه يف حســابه ودفــع بتســليم هــذا املبلــغ ملكفولــه املذكــور وحيــث ان‬\n      ‫هــذا التســليم كان قبــل التثبــت مــن عائديــه املبلــغ وللقاعــدة إذا اختلــف‬\n      ‫الدافــع والقابــض يف صفــة املقبــوض فالقــول قــول الدافــع مــع ميينــه ‪،‬‬\n      ‫صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه للمدعــي‬\n      ‫وإفهــام املدعــى عليــه بــان لــه إقامــة دعــواه فيمــا دفــع بــه جتــاه مكفولــه‬\n      ‫املذكــور اعتــرض املدعــى عليــه علــى احلكــم صــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪109‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 32403744‬وتاريــخ ‪ 1432/09/10‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 321173376‬وتاريــخ ‪ 1432/09/10‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1433/05/05‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 30‬‬\n‫وفيها حضر ‪ ...‬ســجل رقم ‪ ...‬بصفته وكيال عن ‪ ...‬بالوكالة الصادرة‬\n‫مــن كتابــة عــدل املدينــة املنــورة الثانيــة برقــم ‪ 7350‬يف ‪1432/2/4‬ه ـ‬\n‫جلــد ‪ 6771‬واملخــول فيهــا إقامــة الدعــاوى واملرافعــة واإلقــرار واإلنــكار‬\n‫وتقــدمي البينــات والصلــح والتنــازل وقبــول احلكــم ونفيــه وادعــى ضــد‬\n‫‪ ...‬ســجل رقــم ‪ ...‬بصفتــه وكيــا عــن ‪ ... ...‬ســجل رقــم ‪ ...‬بالوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪3361179‬‬\n‫يف ‪1433/4/28‬ه ـ والــذي وكل بصفتــه وكيــا عــن ‪ ...‬ســجل رقــم ‪...‬‬\n‫بصفتــه صاحــب فــرع مؤسســة ‪ ...‬بالوكالــة الصــادرة مــن كتابــة عــدل‬\n‫الدرعيــة برقــم ‪ 310603023272‬يف ‪1432/6/12‬ه ـ ووكالــة املدعــى‬\n‫عليــه ‪ ...‬تخولــه ســماع الدعــاوى والــرد عليهــا والصلــح وإحضــار البينــات‬\n‫وقبــول األحــكام واالعتــراض عليهــا وادعــى األول قائــا إن املدعــى‬\n‫عليــه أصالــة ‪ ...‬قــام بإرســال مندوبــه ومكفولــه ‪ ...‬أردنــي اجلنســية إلــى‬\n‫موكلــي وعــرض عليــه أعماال جتارية على ســبيل الشــراكة وقد اســتلم‬\n‫املدعــى عليــه ‪ ...‬مــن موكلــي مبلغــا قــدرة ســتمائة وســبعون ألــف ريــال‬\n‫أودعــت بحــواالت بنكيــة يف حســاب املدعــى عليــه ‪ ...‬وعنــد مطالبتــه‬\n‫أفــاد بــأن مكفولــه شــخص نصــاب وأنــه هــرب إلــى األردن باألمــوال‬\n\n                                                                                   ‫‪110‬‬\n\f      ‫لــذا أطلــب احلكــم بإلــزام املدعــى عليــه ‪ ...‬بإعــادة املبلــغ املشــار إليــه‬\n      ‫أعــاه إلــى موكلــي هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب‬\n      ‫قائــا مــا ذكــره املدعــي وكالــة أن املدعــو ‪ ...‬هــو منــدوب ملوكلــي‬\n      ‫‪ ...‬فغيــر صحيــح وإمنــا هــو يعمــل حتــت كفالتــه ولــم يرســله موكلــي‬\n      ‫للمدعــي أصالــة ليعــرض عليــه أعمــال جتاريــة علــى ســبيل الشــراكة‬\n      ‫بــل إن موكلــي ‪ ...‬ال يعــرف املدعــي أصالــة وأمــا التحويــات البنكيــة‬\n      ‫فــإن املبلــغ املدعــى بــه قــد مت حتويلــه علــى حســاب مؤسســة موكلــي‬\n      ‫‪ ...‬لصالــح املدعــو ‪ ...‬حيــث إن ذكــر ملوكلــي ‪ ...‬بــأن لــه بذمــة شــخص‬\n      ‫املبلــغ املدعــى بــه وأنــه اتفــق مــع هــذا الشــخص بــأن يحــول لــه ذلــك املبلــغ‬\n      ‫علــى هيئــة حــواالت بنكيــة وأنــه يخشــى مــن املســآءلة مــن قبــل الدوائــر‬\n      ‫املختصــة يف حــال إرســلت احلــواالت حلســابه كونــه مقيــم مبهنــة عامــل‬\n      ‫فقبــل موكلــي ومت إرســال احلــواالت علــى حســاب مؤسســته دون أن‬\n      ‫يحصــل بــن موكلــي واملدعــي أصالــة أي لقــاء أو حتــى مكاملــة وكان‬\n      ‫موكلــي إذا وصلــت احلوالــة حلســاب مؤسســته يســحب قيمتهــا مــن البنك‬\n      ‫ويســلمها نقــدا للمذكــور ‪ ...‬لــذا فــإن موكلــي يطلــب صــرف النظــر عــن‬\n      ‫هــذه الدعــوى وإفهــام املدعــي بــأن يقيــم دعــواه ضــد املذكــور ‪ ... ...‬هــذه‬\n      ‫إجابتــي وبســؤال املدعــى عليــه وكالــة هــل حــول املدعــي أصالــة املبلــغ‬\n      ‫املدعــى بــه يف حســاب مؤسســة موكلــه ‪ ...‬فقــال نعــم وبعــرض إجابــة‬\n      ‫املدعــى عليــه علــى املدعــي قــال الصحيــح مــا ذكرتــه وبســؤال املدعــى‬\n      ‫عليــه وكالــة هــل لديــه بينــة علــى مــا دفــع بــه فقــال ســوف أرجــع ملوكلــي‬\n      ‫وأســأله ورفعــت اجللســة لذلــك وتأجلــت ليــوم الســبت ‪1433/7/19‬ه ـ‬\n      ‫الســاعة ‪ 10.00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/05/05‬ه ـ احلمــد هلل وحــده وبعــد‬\n\n\n‫‪111‬‬\n\f‫فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم الســبت‬\n‫املوافــق‪ 1433/07/19‬ه ـ افتتحــت اجللســة الســاعة ‪1025‬وفيهــا حضــر‬\n‫املدعــي وكالــة واملدعــى عليــه وكالــة املذكوريــن أعــاه وحضــر‬\n‫معهمــا املدعــي أصالــة ‪ ...‬ســجل رقــم ‪ ...‬وبســؤال املدعــى عليــه عمــا‬\n‫طلــب منــه يف اجللســة املاضيــة قــال إننــي أطلــب ســؤال املدعــي أصالــة‬\n‫هــل لــه عالقــة باملدعــو ‪ ...‬يف غيــر هــذا التعامــل وموضــوع القضيــة هــذه‬\n‫فقــال إن املدعــو ‪ ...‬حضــر إلــي قبــل شــهر مــن حتويــل املبلــغ إلــى حســاب‬\n‫مؤسســة املدعــى عليــه وقــال لــي إن كفيلــه هــو املدعــى عليــه أصالــة ‪...‬‬\n‫وأنــه يوجــد مصنــع لألثــاث يعمــل فيــه هــو وكفيلــه ويصــدر منتجاتــه‬\n                                                      ‫لعــدة دول وأن فيــه أربــاح‬\n‫وأن أســم املؤسســة هــي مؤسســة ‪ ...‬فبنــاء علــى ذلــك قمــت بتحويــل املبلــغ‬\n‫املدعــى بــه وأمــا بينتــي علــى مــا دفعــت بــه فهــي التالــي أن بينتــي علــى‬\n‫مــا دفعــت بــه يف املذكــرة املؤرخــة يف ‪1432/11/13‬ه ـ هــي اآلتــي ‪:‬‬\n‫أوال ‪ :‬مــن ان املدعــو ‪ ...‬هــو منــدوب ملوكلــي فغيــر صحيــح وإمنــا هــو‬\n‫يعمــل حتــت كفالتــه مبهنــة (عامــل عــادي) وليــس منــدوب أو يحمــل‬\n‫تفويــض مــن قبــل موكلــي ( مرفــق مســتند رقــم ‪ )1‬ثاني ـ ًا ‪ :‬مــن ان‬\n‫موكلــي أرســل املذكــور ‪ ...‬املدعــي أصالــة ليعــرض عليــه أعمــاال‬\n‫جتاريــة علــى ســبيل الشــراكة فهــذا ليــس صحيح ـ ًا والصحيــح هــو ال‬\n‫توجــد ثمــة معرفــة بينهمــا باألصــل بــل ولــم يســبق أن رآه او مت أي لقــاء‬\n‫أو حتــى مكاملــة وتبــن لنــا مؤخــر ًا ان املدعــي أصالــة وشــقيقه ‪ ...‬همــا‬\n‫صديقــان ل‪ ...‬املذكــور منــذ فتــرة طويلــة وبينهــم تعامــل ســابق ولــدي‬\n‫شــاهد علــى ذلــك مســتعد بإحضــاره عنــد طلبــه ثالثــا‪ :‬مــن أن املدعــي‬\n‫أصالــة أودع بحســاب موكلــي املبلــغ املدعــى بــه علــى هيئــة إيداعــات‬\n\n\n                                                                                      ‫‪112‬‬\n\f      ‫بنكيــة فهــذا ليــس صحيح ـ ًا والصحيــح أن املبلــغ املدعــى بــه قــد مت‬\n      ‫حتويلــه علــى حســاب مؤسســة موكلــي علــى هيئــة حــواالت بنكيــة مــن‬\n      ‫حســاب (مطعــم ‪ )...‬مبلــغ (‪000‬ر‪ )250‬ريــال بتاريــخ ‪2010/7/20‬م ‪ +‬مــن‬\n      ‫حســاب (مطعــم ‪ )...‬مبلــغ (‪000‬ر‪ )200‬ريــال بتاريــخ ‪2010/8/3‬م ‪ +‬مــن‬\n      ‫حســاب املدعــي أصالــة مبلــغ (‪000‬ر‪ )250‬ريــال بتاريــخ ‪2010/8/30‬م‬\n      ‫وليــس كمــا ذكــر املدعــي وجميــع تلــك احلــواالت لصالــح املذكــور ‪...‬‬\n      ‫(مرفــق مســتند رقــم ‪ )2‬رابع ـ ًا ‪ :‬ان املذكــور ‪ ...‬ذكــر ملوكلــي بــأن لــه‬\n      ‫بذمــة شــخص املبلــغ املدعــى بــه وانــه اتفــق مــع ذلــك الشــخص بــأن يحــول‬\n      ‫لــه ذلــك املبلــغ علــى هيئــة حــواالت بنكيــة وانــه يخشــى مــن املســآلة‬\n      ‫مــن قبــل الدوائــر املختصــة يف حــال ارســلت احلــواالت حلســابه كونــه‬\n      ‫مقيــم مبهنــة عامــل فطلــب مــن موكلــي ان يســتخدم حســاب املؤسســة‬\n      ‫يف البنــك فقبــل موكلــي فتــم إرســال احلــواالت علــى حســاب مؤسســته‬\n      ‫ومت التعامــل معــه بالشــكل الرســمي ونرفــق لكــم نســخة مــن ذلــك‬\n      ‫(مرفــق مســتند رقــم ‪ )3‬خامسـ ًا ‪:‬ان املدعــي قــام بالتحويــل إلــى حســاب‬\n      ‫مؤسســة موكلــي بتاريــخ ‪1431/9/21‬ه ـ وانتهــت تأشــيرة اخلــروج‬\n      ‫والعــودة ملكفولــي ‪ ...‬بتاريــخ ‪1431/4/21‬ه ـ ولــم يتقــدم بالدعــوى اال‬\n      ‫بتاريــخ ‪1432/6/19‬ه ـ أي بعــد تســعة أشــهر وهــذا أمــر مريــب سادسـ ًا‬\n      ‫‪ :‬انــه بعــد علمنــا بالدعــوى التــي تقــدم بهــا املدعــي ضــد موكلــي مت‬\n      ‫االتصــال ‪ ...‬ملعرفــة حقيقــة األمــر فأفــاد بأنــه سيرســل إلينــا مايثبــت‬\n      ‫احلقيقــة عــن طريــق احملكمــة يف بلــده األردن وهــو عبــارة عــن إقــرار‬\n      ‫ونرفــق لكــم نســخة منــه (مرفــق مســتند رقــم ‪ )4‬وحيــث ان املدعــي لــم‬\n      ‫يقــدم بينتــه علــى دعــواه وهــذه بينتــي علــى مــا تقدمــت بــه يف املذكــرة‬\n      ‫الســابقة مــن دفــوع كمــا أبــرز صــور شــيكات مســحوبة علــى البنــك‬\n\n\n‫‪113‬‬\n\f‫‪ ...‬األول رقــم ‪ 57‬يف ‪2010/8/31‬م مببلــغ ثمانــن ألــف ريــال والثانــي‬\n‫برقــم ‪ 54‬يف ‪2010/8/30‬م مببلــغ مائــة ألــف ريــال والثالــث برقــم ‪51‬‬\n‫يف ‪2010/7/19‬م مببلــغ مائــة وثمانــن ألــف ريــال والرابــع برقــم ‪53‬‬\n‫يف ‪2010/8/2‬م مببلــغ مائــة وثمانــن ألــف ريــال كلهــا مــن مؤسســة ‪...‬‬\n‫للتجــارة ألمــر ‪ ...‬كمــا أبــرز صــورة ســندات صــرف علــى أوراق مؤسســة‬\n‫‪ ...‬للتجــارة األول رقــم ‪ 45‬يف ‪2010/7/20‬م مببلــغ ســبعني ألــف ريــال‬\n‫والثانــي برقــم ‪ 51‬يف ‪2010/8/3‬م مببلــغ عشــرين ألــف ريــال والثالــث‬\n‫برقــم ‪ 58‬يف ‪2010/8/31‬م مببلــغ أربعــن ألــف ريــال وتتضمــن توقيعــا‬\n‫منســوبا ل‪ ...‬باســتالم املبالــغ املذكــورة يف هــذه الســندات نقــدا وذلــك‬\n‫عــن باقــي قيمــة مبالــغ مودعة باحلســاب التخص العمل أودعت مبعرفة ‪...‬‬\n‫كمــا أبــرز املدعــى عليــه صــورة إقــرار موقــع مــن ‪ ......‬أردني اجلنســية بأن‬\n‫ذمتــه مشــغولة ل‪ ...‬مببلــغ ســتمائة وســبعني ألــف ريــال ســعودي والذي قام‬\n‫بتحويــل حــواالت ماليــة حلســاب مؤسســة ثنائيــة التصميــم للتجــارة والتــي‬\n‫أعمــل لديهــا وذلــك بحســابها لــدى البنــك ‪ ...‬وإن هــذه احلــواالت محولــة‬\n‫لــي شــخصيا وهــي متثــل مديونيــة وحقــوق وتعامــات ســابقة بينــي وبــن ‪...‬‬\n‫‪ ...‬قــام بإيداعهــا حلســاب مؤسســة ثنائيــة التصميــم للتجــارة وأقــر بأننــي‬\n‫تســلمتها كاملــة دون نقــص مــن املؤسســة املذكــورة كونهــا حوالــة‬\n‫خاصــة لــي كمــا أقــر بعــدم عالقــة املؤسســة أو صاحبهــا ‪ ...‬بهــذه احلوالــة‬\n‫ولكونــي أحمــل إقامــة ســعودية مبهنــة عامــل واليحــق إيــداع مثــل هــذا‬\n‫املبلــغ بحســابي الشــخصي فقــد مت االتفــاق بينــي وبــن ‪ ...‬علــى إيداعهــا‬\n‫يف حســاب املؤسســة وقــد أرفــق بهــذا اإلقــرار شــهادة عدليــة مــن كاتــب‬\n‫العــدل يف محكمــة بدايــة شــرق عمــان بــاألردن بتاريــخ ‪2011/6/20‬م‬\n‫بــأن املقــر املذكــور قــد أقــر واعتــرف مبحتوياتــه بحضــور كاتــب‬\n\n\n                                                                                     ‫‪114‬‬\n\f      ‫العــدل وعلــى اإلقــرار مصادقــة ســفارة اململكــة يف عمــان وبعــرض‬\n      ‫هــذه األوراق علــى املدعــي أجــاب املدعــي وكالــة بــأن اإلقــرار املنســوب‬\n      ‫للمدعــو ‪ ...‬فيــه تناقــض يف بدايتــه يقــول أن ذمتــه مشــغوله ملوكلــي ثــم‬\n      ‫يف ثنايــا اإلقــرار يقــول إنهــا محولــه لــه شــخصيا وهــي متثــل مديونيــه‬\n      ‫وحقــوق وتعامــات ســابقه بينــه وبــن موكلــي كمــا أن املدعــو ‪ ...‬هــو‬\n      ‫مكفــول مــن قبــل مؤسســة املدعــى عليــه أصالــة ويعمــل لديهــم وتكلــم‬\n      ‫باســم املدعــى عليــه ونيابــة عنــه وهــو أي ‪ ...‬مــن طلــب التحويــل حلســاب‬\n      ‫املؤسســة ولــو كان املقصــود تســليم املبلــغ ل‪ ...‬لســلمناه لــه مباشــرة‬\n      ‫وليــس عــن طريــق مؤسســة كفيلــه وإذا مت التثبــت مــن كــون الشــخص‬\n      ‫املتفــق معــه حتــت كفالــة املؤسســة التــي ميثلهــا فإنــه يتــم االتفــاق معــه‬\n      ‫وهــذا التعامــل معمــول بــه لــدى جميــع املؤسســات والشــركات كمــا أن‬\n      ‫مؤسســة املدعــى عليــه هــي كفيلــة للمدعــو ‪ ...‬وهــي املســؤولة عنــه وعــن‬\n      ‫تعامالتــه الســيما إذا أودعــت املبالــغ املاليــة يف حســاب الكفيــل ولــم‬\n      ‫تســلم للمكفــول علمــا أن ‪ ...‬هــارب لبلــده األردن ومطلــوب عــن طريــق‬\n      ‫األنتــر بــول الدولــي وبعرضــه علــى املدعــى عليــه وكالــة قــال إنــه اليوجــد‬\n      ‫تناقــض يف اإلقــرار ألن املقــر ذكــر بــأن ذمتــه مشــغولة يف البدايــة ثــم‬\n      ‫فســر ســبب ذلــك وأمــا أن مؤسســة موكلــي مســئولة عــن املدعــو ‪...‬‬\n      ‫فهــذا غيــر صحيــح ألن املدعــي مفــرط كونــه لــم يتصــل علــى املدعــى‬\n      ‫عليــه أصالــة أو يتأكــد ممــا ذكــره املدعــو ‪ ...‬وقــال املدعــي وكالــة‬\n      ‫إن املدعــى عليــه هــو املفــرط كونــه ســلم هــذا املبلــغ للمدعــو ‪ ...‬قبــل‬\n      ‫التأكــد مــن مصــدره وســبب إيداعــه خاصــة وأن هــذا املبلــغ كبيــر‬\n      ‫والــذي اســتلمه هــو وافــد مبهنــة عامــل وبســؤال املدعــى عليــه هــل لديــه‬\n      ‫زيــادة بينــة قــال ليــس لــدي ســوى ماذكــرت وبســؤال املدعــي أصالــة هــل‬\n\n\n‫‪115‬‬\n\f‫هــو مســتعد باليمــن علــى دعــواه قــال نعــم فجــرى تخويفــه مــن عاقبــة‬\n‫اليمــن فقــال ســأحلف ثــم تلفــظ قائــا واهلل العظيــم الــذي الإلــه إال هــو‬\n‫أن ماذكرتــه يف دعــواي ضــد املدعــى عليــه ‪ ...‬صحيــح كلــه واســتحق‬\n‫يف ذمتــه املبلــغ املدعــى بــه وقــدره ســتمائة وســبعون ألــف ريــال حتــى اآلن‬\n‫فبنــاء علــى ماســبق مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه وكالــة‬\n‫بإيــداع املبلــغ املدعــى بــه يف حســاب مؤسســة موكلــه ودفعــه بتســليم‬\n‫هــذا املبلــغ للمدعــو ‪ ...‬ومبــا أن هــذا التســليم الــذي دفــع بــه املدعــى عليــه‬\n‫كان قبــل التثبــت مــن كــون هــذا املبلــغ عائــدا للمدعــو ‪ ...‬مــن عدمــه‬\n‫ولكــون هــذا املبلــغ ملــا أودع يف حســاب مؤسســة املدعــى عليــه أصالــة‬\n‫أصبــح يف مســؤلية صاحــب احلســاب وألن ماذكــره املدعــي ممــا يقــوي‬\n‫كالمــه ولــذا أدى اليمــن عليــه والقاعــدة الفقهيــة تقــول إذا اختلــف‬\n‫الدافــع والقابــض يف صفــة املقبــوض فالقــول قــول الدافــع مــع ميينــه لــذا‬\n‫فقــد حكمــت علــى املدعــى عليــه أصالــة بــأن يدفــع للمدعــي أصالــة‬\n‫املبلــغ املدعــى بــه وقــدره ســتمائة وســبعون ألــف ريــال وأفهمــت املدعــى‬\n‫عليــه وكالــة بأنــه إذا كانــت ملوكلــه مطالبــة ضــد املدعــو ‪ ...‬فلــه‬\n‫إقامتهــا بدعــوى مســتقلة وبعــرض احلكــم علــى املدعــى عليــه وكالــة‬\n‫قــرر عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــه وأفهــم بــأن‬\n‫عليــه املراجعــة يــوم اإلثنــن املوافــق ‪1433/7/21‬ه ـ الســتالم نســخة مــن‬\n‫احلكــم وتقــدمي إعتراضــه عليــه خــال ثالثــن يومــا مــن تاريــخ اســتالم‬\n‫النســخة وأنــه إذا انتهــت املــدة املقــررة نظامــا ولــم يقــدم اعتراضه خاللها‬\n‫ســقط حقــه يف االســتئناف واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪ 1433/07/19‬ه ـ‬\n\n\n                                                                                          ‫‪116‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق‪ 1434/04/30‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09.00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بخطــاب رئيســها رقــم ‪ 34530611‬يف ‪1434/4/13‬ه ـ‬\n      ‫مرفقــا بهــا القــرار رقــم ‪ 34179689‬يف ‪ 1434/4/6‬املتضمــن املصادقــة‬\n      ‫علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪ 1434/04/30‬ه ـ‬\n      ‫احلمــدهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييزالقضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 34220356‬وتاريــخ ‪1434 / 2 / 24‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ ......‬وتاريــخ‬\n      ‫‪1433/ 7 / 23‬ه ـ اخلــاص بدعــوى‪ ... /‬وكالــة ضــد ‪ ... /‬وكالــة‬\n      ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة وأوراق املعاملــة‬\n      ‫وباالطــاع علــى مــا اجــاب فضيلــة القاضــي واحلقــه بالصــك بنــاء علــى‬\n      ‫قرارنــا رقــم ‪ 344755‬وتاريــخ ‪1434/1/6‬ه ـ لــم يظهــر لالكثريــة مــا‬\n      ‫يوجــب املالحظــة بعــد اإليضــاح األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                                         ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":108,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d69982e4ae093c5810b11b681ae728df5c2ae36fd077c4b7a2d78d5e0e688fa6","normalized_text_hash":"4c85f491db1cba19996a5166f2a1f9a386cbd89af1db5398c0c06484efc0c384","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p108-33354636"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

